## Final solution

```js
// index.js
// Run with: node index.js

function linearFindBySku(products, sku) {
  return products.find(product => product.sku === sku) ?? null;
}

function createSkuIndex(products) {
  const index = new Map();

  for (const product of products) {
    if (!index.has(product.sku)) {
      index.set(product.sku, product);
    }
  }

  return index;
}

function indexedFindBySku(index, sku) {
  return index.get(sku) ?? null;
}

function addProduct(products, index, product) {
  if (index.has(product.sku)) {
    throw new Error(`Duplicate SKU: ${product.sku}`);
  }

  products.push(product);
  index.set(product.sku, product);
  return product;
}

function removeProductBySku(products, index, sku) {
  const product = index.get(sku);
  if (!product) return null;

  const position = products.indexOf(product);
  if (position !== -1) {
    products.splice(position, 1);
  }

  index.delete(sku);
  return product;
}

class ProductCatalog {
  constructor(initialProducts = []) {
    this.products = [];
    this.bySku = new Map();

    for (const product of initialProducts) {
      this.add(product);
    }
  }

  add(product) {
    if (this.bySku.has(product.sku)) {
      throw new Error(`Duplicate SKU: ${product.sku}`);
    }

    this.products.push(product);
    this.bySku.set(product.sku, product);
    return product;
  }

  findBySku(sku) {
    return this.bySku.get(sku) ?? null;
  }

  removeBySku(sku) {
    const product = this.bySku.get(sku);
    if (!product) return null;

    const position = this.products.indexOf(product);
    if (position !== -1) this.products.splice(position, 1);

    this.bySku.delete(sku);
    return product;
  }
}

function makeProducts(count) {
  return Array.from({ length: count }, (_, i) => ({
    id: i + 1,
    sku: `SKU-${String(i).padStart(6, "0")}`,
    name: `Product ${i}`,
    price: Math.round(Math.random() * 10000) / 100,
  }));
}

function benchmark() {
  const productCount = 100_000;
  const lookupCount = 1_000;

  const products = makeProducts(productCount);
  const index = createSkuIndex(products);

  // Pick deterministic existing SKUs to query.
  const targets = Array.from(
    { length: lookupCount },
    (_, i) => `SKU-${String((i * 97) % productCount).padStart(6, "0")}`
  );

  const linearStart = performance.now();
  let linearHits = 0;
  for (const sku of targets) {
    if (linearFindBySku(products, sku)) linearHits++;
  }
  const linearMs = performance.now() - linearStart;

  const indexedStart = performance.now();
  let indexedHits = 0;
  for (const sku of targets) {
    if (indexedFindBySku(index, sku)) indexedHits++;
  }
  const indexedMs = performance.now() - indexedStart;

  console.log("Products:", productCount);
  console.log("Lookups:", lookupCount);
  console.log("Linear hits:", linearHits, "time:", linearMs.toFixed(3), "ms");
  console.log("Indexed hits:", indexedHits, "time:", indexedMs.toFixed(3), "ms");
  console.log(
    "Speedup:",
    linearMs === 0 ? "N/A" : (linearMs / Math.max(indexedMs, 0.001)).toFixed(1) + "x"
  );
}

benchmark();
```

### Example output

