## Complexity summary

| Operation | Array only | Array + Map index |
|---|---:|---:|
| Lookup by SKU | `O(n)` | `O(1)` average |
| Insert | `O(1)` amortized | `O(1)` average |
| Delete | `O(n)` | `O(1)` average to `O(n)` due to array splice |
| Memory | `O(n)` | `O(n)` plus index overhead |

## Key takeaways

- An index is a separate access path maintained alongside the data.
- Reads become faster, but writes must update both structures.
- JavaScript `Map` behaves like a hash index: excellent point lookups, not ideal for range or sorted queries.
- Database indexes are often B-trees, which give `O(log n)` point lookups and efficient ordered scans.
- Always define duplicate-key behavior explicitly: unique, first-wins, last-wins, or multi-value index.

## Database Indexes (interview-style explanation)

A **database index** is an auxiliary data structure that lets the engine find rows fast without scanning the whole table.

- **Mental model:** like the index at the back of a book — you look up a term, get page numbers, instead of reading every page.
- **Common structures:**
  - **Hash index:** `O(1)` equality lookups (`WHERE id = 42`), bad for ranges.
  - **B-Tree / B+Tree index:** `O(log n)` search, insert, delete, and efficient range scans (`WHERE age BETWEEN 20 AND 30`, `ORDER BY`).
  - **Bitmap, full-text, spatial indexes:** specialized workloads.
- **Trade-offs:** faster reads, but extra disk/memory, slower writes (every insert/update/delete must update indexes), and maintenance cost.
- **Clustered vs secondary:** clustered index determines physical row order; secondary index stores key → row pointer (or primary key).

Below is a clean, minimal **B-Tree index** in JavaScript (the workhorse behind most relational DB indexes). It supports `insert`, `search`, and ordered `range`.

```js
/**
 * B-Tree Index (in-memory, educational core)
 *
 * - t: minimum degree (max keys = 2t-1, min keys = t-1 except root)
 * - Stores key -> value pairs; keys are unique in this simplified version.
 */

class BTreeNode {
  constructor(t, leaf = true) {
    this.t = t;          // minimum degree
    this.leaf = leaf;    // true if leaf node
    this.keys = [];      // sorted keys
    this.values = [];    // values aligned with keys
    this.children = [];  // child nodes (internal nodes only)
  }
}

class BTreeIndex {
  constructor(t = 3) {
    if (t < 2) throw new Error("minimum degree t must be >= 2");
    this.t = t;
    this.root = new BTreeNode(t, true);
  }

  /** Search a key; returns its value or null. O(log n) */
  search(key, node = this.root) {
    let i = 0;
    while (i < node.keys.length && key > node.keys[i]) i++;

    if (i < node.keys.length && key === node.keys[i]) {
      return node.values[i];
    }
    if (node.leaf) return null;

    return this.search(key, node.children[i]);
  }

  /** Insert a key/value pair, keeping the tree balanced. O(log n) */
  insert(key, value) {
    const root = this.root;

    // If root is full, split it and grow the tree height by one.
    if (root.keys.length === 2 * this.t - 1) {
      const newRoot = new BTreeNode(this.t, false);
      newRoot.children.push(root);
      this._splitChild(newRoot, 0);
      this.root = newRoot;
    }

    this._insertNonFull(this.root, key, value);
  }

  /** Insert into a node that is guaranteed not full. */
  _insertNonFull(node, key, value) {
    let i = node.keys.length - 1;

    if (node.leaf) {
      // Find sorted insertion position and shift.
      while (i >= 0 && key < node.keys[i]) i--;
      // (Simplified: assumes unique keys; in a real DB you'd handle duplicates.)
      node.keys.splice(i + 1, 0, key);
      node.values.splice(i + 1, 0, value);
      return;
    }

    // Internal node: find child to descend into.
    while (i >= 0 && key < node.keys[i]) i--;
    i++;

    const child = node.children[i];
    if (child.keys.length === 2 * this.t - 1) {
      this._splitChild(node, i);
      if (key > node.keys[i]) i++;
    }

    this._insertNonFull(node.children[i], key, value);
  }

  /** Split a full child of parent at index childIndex. */
  _splitChild(parent, childIndex) {
    const t = this.t;
    const child = parent.children[childIndex];
    const newNode = new BTreeNode(t, child.leaf);

    const midIndex = t - 1;
    const midKey = child.keys[midIndex];
    const midValue = child.values[midIndex];

    // Right half moves to newNode.
    newNode.keys = child.keys.splice(t);          // t-1 keys
    newNode.values = child.values.splice(t);      // t-1 values
    // Remove the middle key from child (left keeps t-1 keys).
    child.keys.splice(midIndex, 1);
    child.values.splice(midIndex, 1);

    if (!child.leaf) {
      // Children split: left keeps first t, right gets last t.
      newNode.children = child.children.splice(t);
    }

    // Promote middle key/value into parent.
    parent.keys.splice(childIndex, 0, midKey);
    parent.values.splice(childIndex, 0, midValue);
    parent.children.splice(childIndex + 1, 0, newNode);
  }

  /** Ordered range scan [min, max] (inclusive). O(k + log n) */
  range(min, max, node = this.root, out = []) {
    if (!node) return out;

    for (let i = 0; i <= node.keys.length; i++) {
      // Recurse left child before handling key i.
      if (!node.leaf && i < node.children.length) {
        this.range(min, max, node.children[i], out);
      }
      if (i < node.keys.length) {
        const k = node.keys[i];
        if (k >= min && k <= max) {
          out.push({ key: k, value: node.values[i] });
        }
      }
    }
    return out;
  }
}

// ---------------- Example usage ----------------
const idx = new BTreeIndex(3);

// Insert some rows (key = userId, value = row pointer / record)
for (const [id, name] of [[10, "Alice"], [3, "Bob"], [7, "Carol"], [1, "Dave"], [15, "Eve"], [12, "Frank"]]) {
  idx.insert(id, { id, name });
}

console.log("search(7):", idx.search(7));        // { id: 7, name: 'Carol' }
console.log("search(99):", idx.search(99));       // null
console.log("range(3, 12):", idx.range(3, 12));   // sorted by key

/*
Output:
search(7): { id: 7, name: 'Carol' }
search(99): null
range(3, 12): [
  { key: 3, value: { id: 3, name: 'Bob' } },
  { key: 7, value: { id: 7, name: 'Carol' } },
  { key: 10, value: { id: 10, name: 'Alice' } },
  { key: 12, value: { id: 12, name: 'Frank' } }
]
*/
```

### Notes you’d mention in the interview

- **Hash index variant:** for pure equality lookups, a `Map` is simpler and faster (`O(1)`), but cannot do range scans or `ORDER BY` without sorting.
- **B+Tree in real DBs:** data lives only in leaves; internal nodes are pure separators, and leaves are linked for fast range scans. This code keeps values in every node for simplicity.
- **Concurrency & persistence:** production indexes add locking/latching, WAL, page caching, and crash recovery — far beyond the in-memory core.
- **Duplicates:** real indexes often map one key to many row IDs (non-unique indexes); here keys are unique for clarity.

Below are common database-index edge cases when building Node.js/JavaScript applications, with practical code for each. Examples use MongoDB and PostgreSQL, plus a short IndexedDB section.

## 1. Type mismatches defeat indexes

A numeric index will not match string queries, and in some SQL databases a type mismatch can force a table scan or an error.

```js
// MongoDB
await users.createIndex({ age: 1 });

// Bad: string query against a numeric field
await users.find({ age: req.query.age }).toArray(); // "30" != 30

// Good: normalize at the boundary
const age = Number(req.query.age);
if (!Number.isInteger(age)) throw new Error('invalid age');
await users.find({ age }).toArray();
```

```js
// PostgreSQL / MySQL
// Bad in MySQL: comparing TEXT column to number may coerce the column
await pool.query('SELECT * FROM users WHERE code = $1', [123]); // code is TEXT

// Good: cast in JavaScript or SQL
await pool.query('SELECT * FROM users WHERE code = $1', [String(123)]);
```

## 2. Collation and case sensitivity

If an index was created with a collation, queries must use the same collation or the index may be ignored.

```js
await users.createIndex(
  { email: 1 },
  { collation: { locale: 'en', strength: 2 } } // case-insensitive-ish
);

// Good: match the index collation
await users.find({ email: 'Alice@Example.com' })
  .collation({ locale: 'en', strength: 2 })
  .toArray();

// Bad: default binary collation may not use the index
await users.find({ email: 'Alice@Example.com' }).toArray();
```

## 3. Functions and leading wildcards prevent B-tree use

```sql
-- Usually cannot use a normal index
SELECT * FROM products WHERE LOWER(name) = LOWER($1);
SELECT * FROM products WHERE name LIKE '%phone%';
```

Fix with a functional/trigram index, or normalize data on write:

```sql
CREATE INDEX idx_products_name_lower ON products (LOWER(name));
CREATE INDEX idx_products_name_trgm ON products USING gin (name gin_trgm_ops);
```

```js
// MongoDB: case-insensitive regex often cannot use a normal index well
await products.find({ name: { $regex: /phone/i } }).toArray();

// Better for prefix searches
await products.find({ name: { $regex: /^phone/i } }).toArray();
```

## 4. Compound index prefix and field order

A compound index is useful only when the query follows the index prefix, and equality fields should usually come before range fields.

```js
// Index: tenantId, status, createdAt
await orders.createIndex({ tenantId: 1, status: 1, createdAt: -1 });

// Good: uses full prefix
await orders.find({ tenantId, status: 'paid' })
  .sort({ createdAt: -1 })
  .toArray();

// Bad: status-only query does not use the compound index efficiently
await orders.find({ status: 'paid' }).toArray();

// Design example: if query is tenantId equality + createdAt range + status equality,
// put equalities first:
// { tenantId: 1, status: 1, createdAt: -1 }
```

## 5. Pagination with `skip` becomes slow

Large offsets force the database to scan and discard many rows.

```js
// Bad for large pages
await orders.find({ tenantId })
  .sort({ createdAt: -1 })
  .skip(100000)
  .limit(20)
  .toArray();
```

Use cursor/keyset pagination. Include a tie-breaker such as `_id` for duplicate timestamps.

```js
async function nextPage(tenantId, cursor) {
  const filter = { tenantId };
  if (cursor) {
    const [createdAt, id] = cursor.split('|');
    filter.$or = [
      { createdAt: { $lt: new Date(createdAt) } },
      { createdAt: new Date(createdAt), _id: { $lt: id } }
    ];
  }

  const docs = await orders.find(filter)
    .sort({ createdAt: -1, _id: -1 })
    .limit(20)
    .toArray();

  const last = docs[docs.length - 1];
  const nextCursor = last
    ? `${last.createdAt.toISOString()}|${last._id}`
    : null;

  return { docs, nextCursor };
}
```

## 6. Covering indexes and projections

An index can avoid fetching the document/row only if the query requests indexed fields.

```js
await users.createIndex({ email: 1, name: 1 });

// Better chance of index-only scan
await users.find(
  { email: 'a@example.com' },
  { projection: { _id: 0, email: 1, name: 1 } }
).toArray();
```

In PostgreSQL, use `INCLUDE` for covering indexes:

```sql
CREATE INDEX idx_users_email_covering
ON users (email)
INCLUDE (name, created_at);
```

## 7. Partial and sparse indexes

Partial indexes only apply when the query contains the filter expression.

```js
await users.createIndex(
  { email: 1 },
  { unique: true, partialFilterExpression: { deletedAt: null } }
);

// Good: includes the partial filter
await users.find({ email: 'a@example.com', deletedAt: null }).toArray();

// Bad: may not use the partial index
await users.find({ email: 'a@example.com' }).toArray();
```

Sparse indexes exclude missing fields, but `null` values may still be indexed.

```js
await users.createIndex({ phone: 1 }, { sparse: true, unique: true });

// Multiple documents with phone missing: OK
// Multiple documents with phone: null: may fail unique constraint
```

## 8. Unique-index races and duplicate-key handling

Two concurrent inserts can race even with a unique index. Always handle `E11000`.

```js
async function createUser(email) {
  try {
    return await users.insertOne({ email, createdAt: new Date() });
  } catch (err) {
    if (err.code === 11000) {
      return users.findOne({ email });
    }
    throw err;
  }
}
```

With upserts, retry on duplicate-key errors:

```js
async function upsertUser(email, data) {
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      return await users.updateOne(
        { email },
        { $setOnInsert: { createdAt: new Date() }, $set: data },
        { upsert: true }
      );
    } catch (err) {
      if (err.code !== 11000 || attempt === 2) throw err;
    }
  }
}
```

## 9. Transactions, locks, and read-your-writes

Indexes do not remove locking concerns. In PostgreSQL, index creation can block; use concurrent builds in migrations.

```js
// PostgreSQL migration, outside a transaction
await pool.query('CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_orders_status ON orders (status)');
```

```js
// MongoDB: older apps may set background builds
await orders.createIndex({ status: 1 }, { background: true });
```

For transactional reads, ensure the session/transaction is passed through:

```js
const session = client.startSession();
try {
  await session.withTransaction(async () => {
    await orders.updateOne({ _id }, { $set: { status: 'paid' } }, { session });
    await ledger.insertOne({ orderId: _id }, { session });
  });
} finally {
  await session.endSession();
}
```

## 10. Aggregation pipeline order

Put `$match` and `$sort` early so indexes can be used. Large sorts may need disk.

```js
const result = await orders.aggregate([
  { $match: { tenantId, status: 'paid' } },
  { $sort: { createdAt: -1 } },
  { $limit: 20 },
  { $lookup: { from: 'customers', localField: 'customerId', foreignField: '_id', as: 'customer' } }
], { allowDiskUse: true }).toArray();
```

## 11. Text and geospatial index edge cases

Text indexes have one per collection and language-specific tokenization.

```js
await articles.createIndex(
  { title: 'text', body: 'text' },
  { default_language: 'english', weights: { title: 10 } }
);

await articles.find(
  { $text: { $search: '"node js" -python' } },
  { projection: { score: { $meta: 'textScore' } } }
).sort({ score: { $meta: 'textScore' } }).toArray();
```

Geospatial indexes require `[longitude, latitude]`, not `[lat, lon]`.

```js
await places.createIndex({ location: '2dsphere' });

await places.find({
  location: {
    $near: {
      $geometry: { type: 'Point', coordinates: [lon, lat] },
      $maxDistance: 1000
    }
  }
}).toArray();
```

## 12. ORM/ODM pitfalls

Mongoose can auto-create indexes on startup, which is dangerous in production.

```js
const userSchema = new mongoose.Schema(
  { email: { type: String, required: true } },
  { autoIndex: false } // create indexes in migrations instead
);

userSchema.index({ email: 1 }, { unique: true });
```

Also avoid hidden transformations that change query shape, such as lowercasing in setters without a matching index.

## 13. Verify with `explain`

Do not assume an index is used; measure.

```js
const plan = await orders.find({ tenantId, status: 'paid' })
  .sort({ createdAt: -1 })
  .explain('executionStats');

console.log({
  stage: plan.executionStats.executionStages.stage,
  docsExamined: plan.executionStats.totalDocsExamined,
  returned: plan.executionStats.nReturned
});
```

PostgreSQL:

```js
const { rows } = await pool.query(
  'EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM orders WHERE tenant_id = $1 AND status = $2',
  [tenantId, 'paid']
);
console.log(rows.map(r => r['QUERY PLAN']).join('\n'));
```

## 14. IndexedDB client-side edge cases

IndexedDB indexes are exact-match and case-sensitive; updating an indexed property updates the index automatically.

```js
const request = indexedDB.open('app', 1);

request.onupgradeneeded = (event) => {
  const db = event.target.result;
  const store = db.createObjectStore('users', { keyPath: 'id' });
  store.createIndex('email', 'email', { unique: true });
  store.createIndex('tags', 'tags', { multiEntry: true }); // array values
};

// Range query
const tx = db.transaction('users', 'readonly');
const index = tx.objectStore('users').index('email');
index.getAll(IDBKeyRange.bound('a', 'm')).onsuccess = (e) => {
  console.log(e.target.result);
};
```

Edge cases: boolean/number/string key coercion, `multiEntry` for arrays, transaction scope, and version upgrades blocking if tabs are open.

---

### Practical checklist

- Cast request input to the indexed field's type.
- Match collations exactly.
- Put equality fields before range fields in compound indexes.
- Avoid `skip` for deep pagination; use cursors.
- Include partial-index predicates in queries.
- Handle duplicate-key errors on writes.
- Create production indexes concurrently/background where supported.
- Disable ORM auto-index in production.
- Verify every critical query with `explain`.

Below is a complete, runnable, from-scratch mini database in JavaScript (Node.js). It implements document collections, CRUD, filtering with operators, sorting/pagination/projection, indexes, aggregation, transactions, and JSON persistence.

Save as `mini-db.js` and run with `node mini-db.js`.

```js
// mini-db.js
const fs = require('fs');

class Collection {
  constructor(name) {
    this.name = name;
    this.docs = [];
    this.nextId = 1;
    this.indexes = new Set();      // field names that are indexed
    this._indexMaps = new Map();   // field -> Map(value -> Set<_id>)
  }

  _clone(x) { return JSON.parse(JSON.stringify(x)); }

  _rebuildIndexes() {
    this._indexMaps.clear();
    for (const field of this.indexes) {
      const m = new Map();
      for (const d of this.docs) {
        const v = d[field];
        if (!m.has(v)) m.set(v, new Set());
        m.get(v).add(d._id);
      }
      this._indexMaps.set(field, m);
    }
  }

  createIndex(field) {
    this.indexes.add(field);
    this._rebuildIndexes();
  }

  _id() { return this.nextId++; }

  _match(doc, filter) {
    if (!filter || Object.keys(filter).length === 0) return true;
    if (Array.isArray(filter.$and)) return filter.$and.every(f => this._match(doc, f));
    if (Array.isArray(filter.$or)) return filter.$or.some(f => this._match(doc, f));

    return Object.entries(filter).every(([k, v]) => {
      if (k === '$and' || k === '$or') return true;
      const val = doc[k];

      if (v instanceof RegExp) return v.test(val);
      if (v && typeof v === 'object' && !Array.isArray(v)) {
        if ('$eq' in v) return val === v.$eq;
        if ('$ne' in v) return val !== v.$ne;
        if ('$gt' in v) return val > v.$gt;
        if ('$gte' in v) return val >= v.$gte;
        if ('$lt' in v) return val < v.$lt;
        if ('$lte' in v) return val <= v.$lte;
        if ('$in' in v) return Array.isArray(v.$in) && v.$in.includes(val);
        if ('$nin' in v) return !(Array.isArray(v.$nin) && v.$nin.includes(val));
        if ('$exists' in v) return (val !== undefined) === !!v.$exists;
        if ('$regex' in v) {
          const re = v.$regex instanceof RegExp ? v.$regex : new RegExp(v.$regex, v.$options || '');
          return re.test(val);
        }
        return JSON.stringify(val) === JSON.stringify(v);
      }
      return val === v;
    });
  }

  // Fast path: single equality on an indexed field
  _candidates(filter) {
    if (!filter || filter.$and || filter.$or) return null;
    const keys = Object.keys(filter);
    if (keys.length !== 1) return null;
    const k = keys[0];
    const v = filter[k];
    if (v && typeof v === 'object') return null;
    if (!this.indexes.has(k)) return null;
    const m = this._indexMaps.get(k);
    if (!m || !m.has(v)) return [];
    const ids = m.get(v);
    return this.docs.filter(d => ids.has(d._id));
  }

  insert(doc) {
    const d = { _id: this._id(), ...this._clone(doc), _createdAt: new Date().toISOString() };
    this.docs.push(d);
    this._rebuildIndexes();
    return d._id;
  }

  insertMany(docs) { return docs.map(d => this.insert(d)); }

  find(filter = {}, options = {}) {
    const base = this._candidates(filter);
    let res = (base ? base : this.docs).filter(d => this._match(d, filter));

    if (options.sort) {
      const entries = Object.entries(options.sort);
      res = res.slice().sort((a, b) => {
        for (const [k, dir] of entries) {
          if (a[k] < b[k]) return dir > 0 ? -1 : 1;
          if (a[k] > b[k]) return dir > 0 ? 1 : -1;
        }
        return 0;
      });
    }
    if (options.skip) res = res.slice(options.skip);
    if (options.limit) res = res.slice(0, options.limit);
    if (options.project) {
      res = res.map(d => {
        const o = {};
        for (const k of options.project) if (Object.prototype.hasOwnProperty.call(d, k)) o[k] = d[k];
        return o;
      });
    }
    return this._clone(res);
  }

  findOne(filter = {}, options = {}) {
    return this.find(filter, { ...options, limit: 1 })[0] || null;
  }

  findById(id) {
    const d = this.docs.find(x => x._id === id);
    return d ? this._clone(d) : null;
  }

  count(filter = {}) {
    return this.docs.filter(d => this._match(d, filter)).length;
  }

  _applyUpdate(doc, changes) {
    const hasOp = ['$set', '$inc', '$unset', '$push', '$pull', '$addToSet']
      .some(o => changes && changes[o] !== undefined);

    if (hasOp) {
      if (changes.$set) Object.assign(doc, changes.$set);
      if (changes.$inc) for (const [k, v] of Object.entries(changes.$inc)) doc[k] = (doc[k] || 0) + v;
      if (changes.$unset) for (const k of Object.keys(changes.$unset)) delete doc[k];
      if (changes.$push) for (const [k, v] of Object.entries(changes.$push)) {
        if (!Array.isArray(doc[k])) doc[k] = [];
        doc[k].push(v);
      }
      if (changes.$pull) for (const [k, v] of Object.entries(changes.$pull)) {
        if (Array.isArray(doc[k])) doc[k] = doc[k].filter(x => x !== v);
      }
      if (changes.$addToSet) for (const [k, v] of Object.entries(changes.$addToSet)) {
        if (!Array.isArray(doc[k])) doc[k] = [];
        if (!doc[k].includes(v)) doc[k].push(v);
      }
    } else {
      Object.assign(doc, changes);
    }
    doc._updatedAt = new Date().toISOString();
  }

  updateOne(filter, changes) {
    const idx = this.docs.findIndex(d => this._match(d, filter));
    if (idx === -1) return 0;
    this._applyUpdate(this.docs[idx], this._clone(changes));
    this._rebuildIndexes();
    return 1;
  }

  updateMany(filter, changes) {
    let n = 0;
    this.docs.forEach(d => {
      if (this._match(d, filter)) { this._applyUpdate(d, this._clone(changes)); n++; }
    });
    this._rebuildIndexes();
    return n;
  }

  deleteOne(filter) {
    const idx = this.docs.findIndex(d => this._match(d, filter));
    if (idx === -1) return 0;
    this.docs.splice(idx, 1);
    this._rebuildIndexes();
    return 1;
  }

  deleteMany(filter = {}) {
    const before = this.docs.length;
    this.docs = this.docs.filter(d => !this._match(d, filter));
    this._rebuildIndexes();
    return before - this.docs.length;
  }

  aggregate(pipeline = []) {
    let data = this._clone(this.docs);
    for (const stage of pipeline) {
      if (stage.$match) {
        data = data.filter(d => this._match(d, stage.$match));
      } else if (stage.$group) {
        const g = stage.$group;
        const groups = new Map();
        for (const d of data) {
          const key = (typeof g._id === 'string' && g._id.startsWith('$'))
            ? d[g._id.slice(1)] : g._id;
          if (!groups.has(key)) groups.set(key, { _id: key });
          const acc = groups.get(key);
          for (const [k, v] of Object.entries(g)) {
            if (k === '_id') continue;
            if (v.$sum !== undefined) {
              const field = v.$sum === 1 ? 1
                : (typeof v.$sum === 'string' && v.$sum.startsWith('$') ? d[v.$sum.slice(1)] : v.$sum);
              acc[k] = (acc[k] || 0) + (Number(field) || 0);
            }
            if (v.$avg !== undefined) {
              const field = (typeof v.$avg === 'string' && v.$avg.startsWith('$')) ? d[v.$avg.slice(1)] : v.$avg;
              acc['_sum_' + k] = (acc['_sum_' + k] || 0) + (Number(field) || 0);
              acc['_cnt_' + k] = (acc['_cnt_' + k] || 0) + 1;
              acc[k] = acc['_sum_' + k] / acc['_cnt_' + k];
            }
            if (v.$max !== undefined) {
              const field = (typeof v.$max === 'string' && v.$max.startsWith('$')) ? d[v.$max.slice(1)] : v.$max;
              const num = Number(field);
              acc[k] = acc[k] === undefined ? field : (isNaN(num) ? (field > acc[k] ? field : acc[k]) : Math.max(acc[k], num));
            }
            if (v.$min !== undefined) {
              const field = (typeof v.$min === 'string' && v.$min.startsWith('$')) ? d[v.$min.slice(1)] : v.$min;
              const num = Number(field);
              acc[k] = acc[k] === undefined ? field : (isNaN(num) ? (field < acc[k] ? field : acc[k]) : Math.min(acc[k], num));
            }
            if (v.$push !== undefined) {
              const field = (typeof v.$push === 'string' && v.$push.startsWith('$')) ? d[v.$push.slice(1)] : v.$push;
              if (!Array.isArray(acc[k])) acc[k] = [];
              acc[k].push(field);
            }
          }
        }
        // clean helper keys
        for (const acc of groups.values()) {
          for (const key of Object.keys(acc)) {
            if (key.startsWith('_sum_') || key.startsWith('_cnt_')) delete acc[key];
          }
        }
        data = Array.from(groups.values());
      } else if (stage.$sort) {
        const entries = Object.entries(stage.$sort);
        data = data.slice().sort((a, b) => {
          for (const [k, dir] of entries) {
            if (a[k] < b[k]) return dir >= 0 ? -1 : 1;
            if (a[k] > b[k]) return dir >= 0 ? 1 : -1;
          }
          return 0;
        });
      } else if (stage.$limit) {
        data = data.slice(0, stage.$limit);
      } else if (stage.$skip) {
        data = data.slice(stage.$skip);
      } else if (stage.$project) {
        data = data.map(d => {
          const o = {};
          for (const [k, v] of Object.entries(stage.$project)) {
            if (v === 1) o[k] = d[k];
            else if (typeof v === 'string' && v.startsWith('$')) o[k] = d[v.slice(1)];
          }
          return o;
        });
      }
    }
    return data;
  }

  toJSON() {
    return { name: this.name, nextId: this.nextId, indexes: [...this.indexes], docs: this.docs };
  }

  static fromJSON(o) {
    const c = new Collection(o.name);
    c.nextId = o.nextId || 1;
    c.docs = o.docs || [];
    c.indexes = new Set(o.indexes || []);
    c._rebuildIndexes();
    return c;
  }
}

class MiniDB {
  constructor(name = 'db') {
    this.name = name;
    this.collections = new Map();
  }

  collection(name) {
    if (!this.collections.has(name)) this.collections.set(name, new Collection(name));
    return this.collections.get(name);
  }

  listCollections() { return [...this.collections.keys()]; }
  dropCollection(name) { this.collections.delete(name); }

  _snapshot() {
    const o = {};
    for (const [k, v] of this.collections) o[k] = v.toJSON();
    return JSON.stringify(o);
  }

  _restore(snap) {
    const o = JSON.parse(snap);
    this.collections.clear();
    for (const [k, v] of Object.entries(o)) this.collections.set(k, Collection.fromJSON(v));
  }

  transaction(fn) {
    const snap = this._snapshot();
    try {
      return fn();
    } catch (e) {
      this._restore(snap);
      throw e;
    }
  }

  save(filePath) {
    const o = {};
    for (const [k, v] of this.collections) o[k] = v.toJSON();
    fs.writeFileSync(filePath, JSON.stringify(o, null, 2));
  }

  static load(filePath, name = 'db') {
    const db = new MiniDB(name);
    if (fs.existsSync(filePath)) {
      const o = JSON.parse(fs.readFileSync(filePath, 'utf8'));
      for (const [k, v] of Object.entries(o)) db.collections.set(k, Collection.fromJSON(v));
    }
    return db;
  }
}

module.exports = { MiniDB, Collection };

// ---------------- Demo ----------------
if (require.main === module) {
  const db = new MiniDB('demo');
  const users = db.collection('users');
  users.createIndex('email');

  const id1 = users.insert({ name: 'Alice', email: 'alice@example.com', age: 30, tags: ['admin'] });
  const id2 = users.insert({ name: 'Bob',   email: 'bob@example.com',   age: 25, tags: ['user'] });
  users.insert({ name: 'Carol', email: 'carol@example.com', age: 35, tags: ['user', 'editor'] });

  console.log('All users:', users.find());
  console.log('age > 28:', users.find({ age: { $gt: 28 } }));
  console.log('Indexed lookup:', users.findOne({ email: 'bob@example.com' }));

  users.updateOne({ name: 'Bob' }, { $set: { age: 26 }, $push: { tags: 'beta' } });
  console.log('Bob after update:', users.findOne({ name: 'Bob' }));

  const orders = db.collection('orders');
  orders.insertMany([
    { userId: id1, product: 'Book', qty: 2, price: 10 },
    { userId: id1, product: 'Pen',  qty: 5, price: 2 },
    { userId: id2, product: 'Book', qty: 1, price: 10 },
  ]);
  console.log('Orders for Alice:', orders.find({ userId: id1 }));

  console.log('Aggregation (qty totals per user):', orders.aggregate([
    { $group: { _id: '$userId', totalQty: { $sum: '$qty' }, orderCount: { $sum: 1 } } },
    { $sort: { totalQty: -1 } },
  ]));

  // Transaction rollback demo
  try {
    db.transaction(() => {
      users.insert({ name: 'Dave', email: 'dave@example.com', age: 40 });
      throw new Error('rollback demo');
    });
  } catch (e) {
    console.log('Transaction rolled back:', e.message);
  }
  console.log('User count after rollback:', users.count());

  // Persistence demo
  const file = '/tmp/mini-db.json';
  db.save(file);
  const db2 = MiniDB.load(file);
  console.log('Loaded collections:', db2.listCollections());
  console.log('Loaded user count:', db2.collection('users').count());

  // Delete demo
  users.deleteMany({ age: { $lt: 26 } });
  console.log('After delete:', users.find({}, { project: ['name', 'age'] }));
}
```

### What it demonstrates

- **Collections & documents**: auto-increment `_id`, timestamps.
- **CRUD**: `insert`, `insertMany`, `find`, `findOne`, `findById`, `updateOne`, `updateMany`, `deleteOne`, `deleteMany`, `count`.
- **Query operators**: `$eq`, `$ne`, `$gt`, `$gte`, `$lt`, `$lte`, `$in`, `$nin`, `$exists`, `$regex`, plus `$and`/`$or`.
- **Find options**: `sort`, `skip`, `limit`, `project`.
- **Indexes**: `createIndex(field)` with an indexed fast path for single-key equality filters.
- **Update operators**: `$set`, `$inc`, `$unset`, `$push`, `$pull`, `$addToSet`.
- **Aggregation pipeline**: `$match`, `$group` (`$sum`, `$avg`, `$max`, `$min`, `$push`), `$sort`, `$skip`, `$limit`, `$project`.
- **Transactions**: snapshot/restore rollback on thrown errors.
- **Persistence**: `save` / `MiniDB.load` to JSON.

Run it with `node mini-db.js` to see all features in action.

# Databases in JavaScript: Basics

JavaScript itself has no built-in database. In practice:

- **In the browser** you talk to client-side storage (IndexedDB, localStorage, etc.) or to a remote API.
- **On the server (Node.js)** you connect to real databases using drivers/ORMs.

The core idea is always the same: **open a connection → send commands/queries → get results → close/clean up**, all using **asynchronous** APIs.

---

## 1. The Idea

| Concept | What it means in JS |
|---|---|
| **Driver** | Low-level library that speaks the DB protocol (e.g. `pg`, `mysql2`, `mongodb`) |
| **ORM/ODM** | Higher-level mapper between JS objects and DB rows/documents (Prisma, Sequelize, Mongoose) |
| **Connection pool** | Reuses TCP connections instead of opening one per query |
| **Parameterized queries** | Pass values separately from SQL text → prevents SQL injection |
| **Async I/O** | All DB calls return Promises; use `async/await` |

---

## 2. Syntax Essentials (Node.js + PostgreSQL)

Install:

```bash
npm install pg
```

```js
// db.js
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pass@localhost:5432/app
  max: 10, // pool size
});

export async function getUser(id) {
  // $1 is a placeholder; values are sent separately (safe)
  const { rows } = await pool.query(
    'SELECT id, name, email FROM users WHERE id = $1',
    [id]
  );
  return rows[0] ?? null;
}

export async function createUser(name, email) {
  const { rows } = await pool.query(
    'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING id, name, email',
    [name, email]
  );
  return rows[0];
}

// Graceful shutdown
process.on('SIGINT', async () => {
  await pool.end();
  process.exit(0);
});
```

Usage:

```js
import { getUser, createUser } from './db.js';

const user = await createUser('Ada', 'ada@example.com');
console.log(user); // { id: 1, name: 'Ada', email: 'ada@example.com' }

const found = await getUser(1);
console.log(found?.name); // 'Ada'
```

**CRUD pattern:** `SELECT`, `INSERT`, `UPDATE`, `DELETE` are just strings. The driver handles escaping via placeholders.

```js
await pool.query('UPDATE users SET name = $1 WHERE id = $2', ['Grace', 1]);
await pool.query('DELETE FROM users WHERE id = $1', [1]);
```

---

## 3. NoSQL Example (MongoDB + Mongoose)

Install:

```bash
npm install mongoose
```

```js
// models/User.js
import mongoose from 'mongoose';

const userSchema = new mongoose.Schema({
  name: { type: String, required: true },
  email: { type: String, required: true, unique: true },
  createdAt: { type: Date, default: Date.now },
});

export const User = mongoose.model('User', userSchema);
```

```js
// app.js
import mongoose from 'mongoose';
import { User } from './models/User.js';

await mongoose.connect(process.env.MONGO_URI);

const ada = await User.create({ name: 'Ada', email: 'ada@example.com' });
console.log(ada._id);

const found = await User.findOne({ email: 'ada@example.com' }).lean();
console.log(found?.name);

await User.updateOne({ _id: ada._id }, { name: 'Ada Lovelace' });
await User.deleteOne({ _id: ada._id });

await mongoose.disconnect();
```

**Key difference from SQL:** documents are flexible; queries use JS objects instead of SQL strings.

---

## 4. Client-Side: IndexedDB (Browser)

For offline/local data in the browser:

```js
const req = indexedDB.open('mydb', 1);

req.onupgradeneeded = (e) => {
  const db = e.target.result;
  db.createObjectStore('notes', { keyPath: 'id', autoIncrement: true });
};

req.onsuccess = (e) => {
  const db = e.target.result;
  const tx = db.transaction('notes', 'readwrite');
  const store = tx.objectStore('notes');
  store.add({ text: 'Hello', createdAt: Date.now() });
  tx.oncomplete = () => console.log('saved');
};
```

Usually wrapped by libraries like **Dexie.js** for saner syntax.

---

## 5. Best Practices

1. **Never concatenate user input into queries** (SQL injection). Always use placeholders (`$1`, `?`, or ORM methods).
2. **Use a pool**, not a single connection, in servers.
3. **Close connections** on shutdown (important in serverless/containers).
4. **Validate & sanitize at the boundary** (Zod/Joi) before DB calls.
5. **Use transactions** for multi-step writes:
   ```js
   const client = await pool.connect();
   try {
     await client.query('BEGIN');
     await client.query('INSERT INTO orders ...');
     await client.query('UPDATE inventory ...');
     await client.query('COMMIT');
   } catch (e) {
     await client.query('ROLLBACK');
     throw e;
   } finally {
     client.release();
   }
   ```
6. **Migrations**: manage schema changes with tools like Prisma Migrate, Knex, or `node-pg-migrate`.

---

## 6. Typical Use Cases

- **REST/GraphQL APIs**: Node + Express/Fastify + Postgres/MongoDB.
- **Serverless (AWS Lambda, Vercel)**: Use serverless-friendly drivers (Neon, PlanetScale, MongoDB Atlas) or connection caching.
- **Real-time apps**: Combine DB with WebSockets; changes pushed via change streams (MongoDB) or LISTEN/NOTIFY (Postgres).
- **Caching layer**: Redis (`ioredis`) in front of primary DB for hot reads.
- **Local-first/offline apps**: IndexedDB + sync to server.

---

## 7. Quick Comparison: Driver vs ORM

| | Raw driver (`pg`) | ORM (Prisma) |
|---|---|---|
| Control | Full SQL | Generated queries |
| Boilerplate | More | Less |
| Type safety | Manual | Strong (with TS) |
| Learning | SQL required | Schema-first |

**Prisma example (type-safe):**

```js
import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

const user = await prisma.user.create({
  data: { name: 'Ada', email: 'ada@example.com' },
});
const users = await prisma.user.findMany({ where: { name: 'Ada' } });
```

---

### Summary mental model

```
JS App ──(driver/ORM)──► Database
   │                          │
   └── async/await + pool ───┘
   └── placeholders = safe ──┘
```

Start with a **driver + connection pool** to learn SQL/queries, then adopt an **ORM** (Prisma/Mongoose) when you want less boilerplate and better TypeScript support.

## Mistake: SQL injection via string interpolation

```js
// db.js
const { Pool } = require('pg');
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

async function getUserByUsername(username) {
  // BAD: interpolating user input directly into SQL
  const sql = `SELECT id, email FROM users WHERE username = '${username}'`;
  const { rows } = await pool.query(sql);
  return rows[0];
}

module.exports = { getUserByUsername };
```

### What goes wrong

If `username` is something like:

```
' OR '1'='1
```

the resulting query becomes:

```sql
SELECT id, email FROM users WHERE username = '' OR '1'='1'
```

which returns every row in the table. Worse inputs can drop tables, exfiltrate data, or modify records. The root cause is treating user input as *code* instead of *data*.

A second, subtler issue: even with “safe” inputs, quoting/escaping rules differ between databases and drivers, so hand-rolled escaping is fragile.

---

## Corrected version

```js
// db.js
const { Pool } = require('pg');
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

async function getUserByUsername(username) {
  // GOOD: parameterized query; the driver sends SQL and params separately
  const sql = 'SELECT id, email FROM users WHERE username = $1';
  const { rows } = await pool.query(sql, [username]);
  return rows[0] ?? null;
}

module.exports = { getUserByUsername };
```

### Why this fixes it

- **Separation of code and data.** The SQL text is fixed; `username` is sent as a bound parameter. The database parses the query plan once and treats the value purely as data, so metacharacters cannot alter the statement structure.
- **Driver-level safety.** `pg` (and most drivers) handles proper encoding/escaping for the target database’s protocol, including types, NULLs, and unicode.
- **Predictable types.** Bound parameters preserve types (e.g., numbers stay numbers), avoiding implicit casts that can cause surprising behavior or index misses.
- **`?? null`** makes “not found” explicit instead of returning `undefined`, which reduces downstream `undefined`-related bugs.

### Additional best practices worth adding

```js
async function getUserByUsername(username) {
  if (typeof username !== 'string' || username.length === 0) {
    throw new TypeError('username must be a non-empty string');
  }
  const sql = 'SELECT id, email FROM users WHERE username = $1';
  try {
    const { rows } = await pool.query(sql, [username]);
    return rows[0] ?? null;
  } catch (err) {
    // Log with context, but don't leak SQL details to callers
    console.error('getUserByUsername failed', { username, err: err.message });
    throw err;
  }
}
```

- Validate input shape before hitting the DB.
- Handle errors explicitly; don’t let raw driver errors propagate to HTTP responses.
- Reuse a single `Pool` (as shown) rather than creating a new client per query—connection churn is a common secondary mistake.
- Prefer an ORM/query builder (Prisma, Knex, Drizzle) for complex apps, but still understand that they ultimately generate parameterized queries under the hood.

### Quick test you can run mentally

With the corrected code, input `' OR '1'='1` is sent as a literal string value. The DB looks for a user whose username is exactly `' OR '1'='1`; no rows match, and no injection occurs.

Below are the most common pitfalls when doing “database basics” in JavaScript (usually Node.js), with bad vs. good code for each.

---

## 1. SQL injection from string interpolation

**Pitfall:** Building queries with template literals or `+`.

```js
// BAD
const email = req.body.email;
const rows = await db.query(`SELECT * FROM users WHERE email = '${email}'`);
```

**Fix:** Always use parameterized queries.

```js
// GOOD (pg)
const { rows } = await pool.query(
  'SELECT * FROM users WHERE email = $1',
  [req.body.email]
);

// GOOD (mysql2)
const [rows] = await pool.execute(
  'SELECT * FROM users WHERE email = ?',
  [req.body.email]
);
```

---

## 2. Forgetting `await` (fire-and-forget writes)

**Pitfall:** The query starts, but you don’t wait for it. Errors disappear and ordering breaks.

```js
// BAD
function createUser(data) {
  pool.query('INSERT INTO users(name) VALUES($1)', [data.name]);
  return { ok: true }; // responds before DB finishes
}
```

**Fix:** Await and handle errors.

```js
// GOOD
async function createUser(data) {
  await pool.query('INSERT INTO users(name) VALUES($1)', [data.name]);
  return { ok: true };
}
```

---

## 3. Connection leaks (not releasing clients)

**Pitfall:** Checking out a client from a pool and never releasing it.

```js
// BAD
const client = await pool.connect();
const { rows } = await client.query('SELECT 1');
// forgot client.release()
```

**Fix:** Use `try/finally`, or prefer `pool.query()` for single statements.

```js
// GOOD
const client = await pool.connect();
try {
  const { rows } = await client.query('SELECT 1');
  return rows;
} finally {
  client.release();
}

// Even simpler for one query:
const { rows } = await pool.query('SELECT 1');
```

---

## 4. Creating a new connection per request

**Pitfall:** Opening/closing DB connections inside route handlers.

```js
// BAD
app.get('/users', async (req, res) => {
  const client = new Client(dbConfig);
  await client.connect();
  const { rows } = await client.query('SELECT * FROM users');
  await client.end();
  res.json(rows);
});
```

**Fix:** Create one pool at startup and reuse it.

```js
// GOOD
const pool = new Pool(dbConfig);

app.get('/users', async (req, res) => {
  const { rows } = await pool.query('SELECT * FROM users');
  res.json(rows);
});
```

---

## 5. Mixing callbacks and promises

**Pitfall:** Half callback, half async/await leads to unhandled errors.

```js
// BAD
pool.query('SELECT * FROM users', (err, res) => {
  if (err) throw err; // thrown inside callback -> unhandled
  console.log(res.rows);
});
```

**Fix:** Use one style consistently; prefer promises.

```js
// GOOD
try {
  const { rows } = await pool.query('SELECT * FROM users');
  console.log(rows);
} catch (err) {
  console.error(err);
}
```

---

## 6. N+1 queries

**Pitfall:** Querying inside a loop.

```js
// BAD
const { rows: users } = await pool.query('SELECT id, name FROM users');
for (const user of users) {
  const { rows: orders } = await pool.query(
    'SELECT * FROM orders WHERE user_id = $1',
    [user.id]
  );
  user.orders = orders;
}
```

**Fix:** Use a JOIN or batched `IN (...)`.

```js
// GOOD
const { rows } = await pool.query(`
  SELECT u.id, u.name, o.id AS order_id, o.total
  FROM users u
  LEFT JOIN orders o ON o.user_id = u.id
`);
// group in JS, or better, let SQL aggregate
```

---

## 7. Race conditions without transactions

**Pitfall:** Read-modify-write across requests can overwrite each other.

```js
// BAD
async function incrementCounter(id) {
  const { rows } = await pool.query('SELECT count FROM counters WHERE id=$1', [id]);
  const next = rows[0].count + 1;
  await pool.query('UPDATE counters SET count=$1 WHERE id=$2', [next, id]);
}
```

**Fix:** Use atomic SQL or a transaction with locking.

```js
// GOOD: atomic
await pool.query('UPDATE counters SET count = count + 1 WHERE id = $1', [id]);

// GOOD: transaction when multiple statements must succeed together
const client = await pool.connect();
try {
  await client.query('BEGIN');
  await client.query('UPDATE accounts SET balance = balance - $1 WHERE id=$2', [amount, from]);
  await client.query('UPDATE accounts SET balance = balance + $1 WHERE id=$2', [amount, to]);
  await client.query('COMMIT');
} catch (e) {
  await client.query('ROLLBACK');
  throw e;
} finally {
  client.release();
}
```

---

## 8. Storing money as floating point

**Pitfall:** `number` in JS is IEEE-754; cents get lost.

```js
// BAD
await pool.query('INSERT INTO payments(amount) VALUES($1)', [19.99]);
// later: 19.990000000000002
```

**Fix:** Store as integer cents (or use `DECIMAL`/`NUMERIC` and a decimal library).

```js
// GOOD
await pool.query('INSERT INTO payments(amount_cents) VALUES($1)', [1999]);

// Or with pg + numeric, parse carefully:
// amount NUMERIC(12,2) -> returns string in pg; convert with decimal.js
```

---

## 9. Date/timezone confusion

**Pitfall:** Inserting JS `Date` objects and assuming UTC/local consistency.

```js
// BAD (ambiguous)
await pool.query('INSERT INTO events(starts_at) VALUES($1)', [new Date()]);
```

**Fix:** Normalize to UTC ISO strings or epoch; store as `timestamptz`.

```js
// GOOD
const utcIso = new Date().toISOString(); // explicit UTC
await pool.query('INSERT INTO events(starts_at) VALUES($1)', [utcIso]);

// When reading, format in the app or DB:
const { rows } = await pool.query(
  "SELECT starts_at AT TIME ZONE 'UTC' AS starts_at_utc FROM events"
);
```

---

## 10. Blocking the event loop

**Pitfall:** Using synchronous DB drivers or doing heavy work on large result sets in the main thread.

```js
// BAD (better-sqlite3 sync inside request handler)
app.get('/big', (req, res) => {
  const rows = db.prepare('SELECT * FROM big_table').all(); // blocks
  res.json(rows);
});
```

**Fix:** Prefer async drivers; for unavoidable sync (e.g., SQLite), offload to worker threads or stream.

```js
// GOOD: stream rows
const stream = pool.query(new Query('SELECT * FROM big_table'));
stream.on('row', (row) => processRow(row));
stream.on('end', () => res.end());
```

---

## 11. Loading huge tables into memory

**Pitfall:** `SELECT *` on large tables causes memory spikes.

```js
// BAD
const { rows } = await pool.query('SELECT * FROM logs'); // millions of rows
```

**Fix:** Paginate or stream.

```js
// GOOD: keyset pagination
const { rows } = await pool.query(
  'SELECT * FROM logs WHERE id > $1 ORDER BY id LIMIT $2',
  [lastId, 1000]
);

// GOOD: cursor/stream (pg-query-stream)
const query = new QueryStream('SELECT * FROM logs');
const stream = pool.query(query);
stream.pipe(transform).pipe(res);
```

---

## 12. Hardcoded credentials / secrets in code

**Pitfall:** Committing DB URLs or passwords.

```js
// BAD
const pool = new Pool({ connectionString: 'postgres://admin:secret@prod/db' });
```

**Fix:** Use environment variables and a secrets manager.

```js
// GOOD
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: true } : false,
});
```

---

## 13. Not handling DB errors specifically

**Pitfall:** Generic try/catch hides unique-constraint failures, etc.

```js
// BAD
try {
  await pool.query('INSERT INTO users(email) VALUES($1)', [email]);
} catch (e) {
  res.status(500).send('something broke');
}
```

**Fix:** Inspect error codes.

```js
// GOOD (pg)
try {
  await pool.query('INSERT INTO users(email) VALUES($1)', [email]);
} catch (e) {
  if (e.code === '23505') { // unique_violation
    return res.status(409).send('email already exists');
  }
  throw e; // let global handler log 500
}
```

---

## 14. ORM: N+1 and lazy loading surprises

**Pitfall:** Accessing relations in a loop triggers extra queries.

```js
// BAD (Prisma-like)
const users = await prisma.user.findMany();
for (const u of users) {
  console.log(u.posts.length); // extra query each iteration
}
```

**Fix:** Eager load with `include`/`join`.

```js
// GOOD
const users = await prisma.user.findMany({
  include: { posts: true },
});
```

---

## 15. Comparing IDs with `==` or wrong types

**Pitfall:** Postgres `BIGINT` may arrive as string (in `pg`), causing `===` failures.

```js
// BAD
if (row.user_id === req.params.id) { ... } // '42' !== 42
```

**Fix:** Normalize types explicitly.

```js
// GOOD
const userId = Number(req.params.id);
if (row.user_id === userId) { ... }

// Or compare as strings consistently:
if (String(row.user_id) === String(req.params.id)) { ... }
```

---

## 16. Forgetting to close pool on shutdown

**Pitfall:** Process hangs because connections stay open.

```js
// BAD
process.on('SIGTERM', () => process.exit(0));
```

**Fix:** Drain the pool.

```js
// GOOD
process.on('SIGTERM', async () => {
  await pool.end();
  process.exit(0);
});
```

---

### Quick checklist

- Use parameterized queries (`$1`, `?`).
- One pool, created once.
- Always `await` DB calls and wrap in `try/catch`.
- Release clients in `finally`.
- Use transactions for multi-step writes.
- Store money in cents / `NUMERIC`.
- Normalize dates to UTC.
- Paginate or stream large reads.
- Keep secrets in env vars.
- Handle DB-specific error codes.
- Eager-load ORM relations.
- Normalize ID types.
- Close pool on shutdown.

If you tell me which stack you’re using (pg, mysql2, Prisma, Mongoose, SQLite, etc.), I can tailor these to exact APIs and error codes.

## Exercise

**Task:** Build a tiny *in-memory database of books* in JavaScript with the following operations:

- `insert(book)` — add a book (`{ title, author, year }`), auto-generate an `id`.
- `findById(id)` — return one book or `null`.
- `findAll(filter)` — return all books, optionally filtered by `author` and/or `minYear`.
- `update(id, patch)` — partially update a book; return updated book or `null`.
- `remove(id)` — delete a book; return `true`/`false`.

Then demonstrate all operations in a short script.

---

## Step-by-step solution

### Step 1 — Model and store
A "table" is just an array of objects. We keep a counter for auto-incrementing ids (like `AUTOINCREMENT` in SQL).

### Step 2 — Insert
Clone the input (don't mutate caller data), assign a new id, push, return the stored record.

### Step 3 — Find
`findById` is O(n) linear scan (fine for small data; an index/Map would be the real-DB optimization). `findAll` filters with optional predicates.

### Step 4 — Update
Find by id, `Object.assign` the patch, return the record. Keep it immutable-ish by returning the same stored object (typical for in-memory).

### Step 5 — Delete
Find index, `splice`, return boolean.

### Step 6 — Demo
Seed a few books, then run queries.

---

## Final solution

Save as `books-db.js` and run with `node books-db.js`.

```js
// books-db.js
// A tiny in-memory "database" demonstrating CRUD basics in JavaScript.

class BooksDb {
  constructor() {
    this.books = [];
    this.nextId = 1;
  }

  // CREATE
  insert({ title, author, year }) {
    if (!title || !author || typeof year !== "number") {
      throw new Error("insert requires { title, author, year:number }");
    }
    const book = { id: this.nextId++, title, author, year };
    this.books.push(book);
    return { ...book }; // return a copy
  }

  // READ one
  findById(id) {
    const book = this.books.find((b) => b.id === id);
    return book ? { ...book } : null;
  }

  // READ many (with optional filters)
  findAll({ author, minYear } = {}) {
    return this.books
      .filter((b) => (author ? b.author === author : true))
      .filter((b) => (typeof minYear === "number" ? b.year >= minYear : true))
      .map((b) => ({ ...b }));
  }

  // UPDATE (partial)
  update(id, patch) {
    const book = this.books.find((b) => b.id === id);
    if (!book) return null;
    // only allow known fields
    const { title, author, year } = patch;
    if (title !== undefined) book.title = title;
    if (author !== undefined) book.author = author;
    if (year !== undefined) {
      if (typeof year !== "number") throw new Error("year must be a number");
      book.year = year;
    }
    return { ...book };
  }

  // DELETE
  remove(id) {
    const idx = this.books.findIndex((b) => b.id === id);
    if (idx === -1) return false;
    this.books.splice(idx, 1);
    return true;
  }

  // helper for demos
  count() {
    return this.books.length;
  }
}

// ---------- Demo ----------
const db = new BooksDb();

// Seed
const a = db.insert({ title: "Dune", author: "Frank Herbert", year: 1965 });
const b = db.insert({ title: "1984", author: "George Orwell", year: 1949 });
const c = db.insert({ title: "Foundation", author: "Isaac Asimov", year: 1951 });

console.log("seeded:", db.count(), "books");
console.log("findById(2):", db.findById(2));

// Filter: Orwell books from 1900+
console.log("findAll({ author:'George Orwell', minYear:1900 }):",
  db.findAll({ author: "George Orwell", minYear: 1900 }));

// Partial update
console.log("update(1, { year: 1966 }):", db.update(1, { year: 1966 }));

// Delete
console.log("remove(999):", db.remove(999)); // false
console.log("remove(2):", db.remove(2));     // true
console.log("after delete count:", db.count());
console.log("all remaining:", db.findAll());
```

### Expected output (approx)
```
seeded: 3 books
findById(2): { id: 2, title: '1984', author: 'George Orwell', year: 1949 }
findAll({ author:'George Orwell', minYear:1900 }): [ { id: 2, ... } ]
update(1, { year: 1966 }): { id: 1, title: 'Dune', author: 'Frank Herbert', year: 1966 }
remove(999): false
remove(2): true
after delete count: 2
all remaining: [ { id: 1, ... }, { id: 3, ... } ]
```

