## 4. Error handling patterns

```js
// ---------- 10. try / catch / finally ----------
function readFileFake(path) {
  try {
    if (!path) throw new TypeError('path is required');
    if (path === 'missing.txt') throw new Error('ENOENT: no such file');
    return `contents of ${path}`;
  } catch (err) {
    // Re-throw with added context, preserving cause (ES2022)
    throw new Error(`readFileFake failed for ${path}`, { cause: err });
  } finally {
    // always runs (cleanup)
    console.log('finally: cleanup for', path);
  }
}

for (const p of [null, 'missing.txt', 'ok.txt']) {
  try {
    console.log(readFileFake(p));
  } catch (e) {
    console.error('Caught:', e.message);
    console.error('Cause:', e.cause && e.cause.message);
  }
}

// ---------- 11. Global handlers (Node) ----------
process.on('uncaughtException', (err, origin) => {
  console.error('UNCAUGHT:', err.stack || err, 'origin=', origin);
  // In production you'd log + exit; here we just note it.
});
process.on('unhandledRejection', (reason, promise) => {
  console.error('UNHANDLED REJECTION:', reason);
});
```

