## Final solution

```js
const OrderStatus = Object.freeze({
  PENDING: "PENDING",
  PROCESSING: "PROCESSING",
  SHIPPED: "SHIPPED",
  DELIVERED: "DELIVERED",
  CANCELLED: "CANCELLED",
});

function isOrderStatus(value) {
  return Object.values(OrderStatus).includes(value);
}

const ALLOWED_TRANSITIONS = new Map([
  [OrderStatus.PENDING, new Set([OrderStatus.PROCESSING, OrderStatus.CANCELLED])],
  [OrderStatus.PROCESSING, new Set([OrderStatus.SHIPPED, OrderStatus.CANCELLED])],
  [OrderStatus.SHIPPED, new Set([OrderStatus.DELIVERED])],
  [OrderStatus.DELIVERED, new Set()],
  [OrderStatus.CANCELLED, new Set()],
]);

function canTransition(from, to) {
  if (!isOrderStatus(from) || !isOrderStatus(to)) return false;
  return ALLOWED_TRANSITIONS.get(from)?.has(to) ?? false;
}

class Order {
  constructor(id) {
    this.id = id;
    this.status = OrderStatus.PENDING;
  }

  transitionTo(nextStatus) {
    if (!canTransition(this.status, nextStatus)) {
      throw new Error(`Invalid transition: ${this.status} -> ${nextStatus}`);
    }
    this.status = nextStatus;
  }
}

// --- Quick checks ---
const order = new Order(1);

order.transitionTo(OrderStatus.PROCESSING);
order.transitionTo(OrderStatus.SHIPPED);
order.transitionTo(OrderStatus.DELIVERED);

console.log(order.status); // "DELIVERED"

console.log(canTransition(OrderStatus.PENDING, OrderStatus.SHIPPED)); // false
console.log(canTransition(OrderStatus.PENDING, OrderStatus.CANCELLED)); // true
console.log(isOrderStatus("SHIPPED")); // true
console.log(isOrderStatus("UNKNOWN")); // false

try {
  order.transitionTo(OrderStatus.CANCELLED);
} catch (err) {
  console.log(err.message); // Invalid transition: DELIVERED -> CANCELLED
}
```

### Notes

- `Object.freeze` prevents adding, removing, or changing top-level keys, which is enough for most enum use cases.
- String values are preferred over numbers for readability and safer debugging.
- If you need guaranteed unique values at runtime, you can use `Symbol`, but that makes serialization and JSON logging harder.
- In TypeScript, the equivalent is usually a string enum or a `const` object with `as const`, depending on your style.

## Enums in JavaScript (interview overview)

JavaScript has **no native `enum` keyword** (unlike TypeScript, C#, Java). In JS we emulate enums with:

1. **Plain object constants**
   ```js
   const Status = { PENDING: 0, DONE: 1 };
   ```
   Simple, but mutable and has no reverse lookup.

2. **Frozen object constants**
   ```js
   const Status = Object.freeze({ PENDING: 0, DONE: 1 });
   ```
   Immutable, but still no auto-increment, validation, or reverse mapping.

3. **Symbol-based enums**
   ```js
   const Status = Object.freeze({ PENDING: Symbol('PENDING'), ... });
   ```
   Great for uniqueness/privacy, but not serializable and no reverse lookup by default.

4. **TypeScript enums** (compile-time)
   - Numeric enums get automatic reverse mapping (`Color[0] === 'Red'`).
   - String enums are one-way.
   - `const enum` is inlined at compile time.

**Core behaviors an enum should provide**
- Named constants (keys)
- Associated values
- Immutability (frozen)
- Membership checks
- Iteration over keys/values
- Optional reverse lookup (name ↔ value)
- Validation to prevent duplicates/invalid definitions

---

## Implementation: a small enum factory

Below is a clean, dependency-free factory that supports both:
- **Numeric enums** from an array of names (`['A','B'] → {A:0,B:1}` + reverse mapping)
- **String/numeric enums** from an object (`{ A: 'apple', B: 'banana' }`)

It freezes the result, attaches non-enumerable helpers, and validates input.

```js
/**
 * Create an immutable enum.
 *
 * @param {string[] | Record<string, string|number>} definition
 *   - Array of strings  → numeric enum: { RED:0, GREEN:1, ... } with reverse mapping.
 *   - Object mapping    → enum with the given values.
 * @returns {Readonly<Object>} Frozen enum object with helper methods.
 *
 * Helpers (non-enumerable):
 *   enum.keys()     -> string[]
 *   enum.values()   -> (string|number)[]
 *   enum.hasKey(k)  -> boolean
 *   enum.hasValue(v)-> boolean
 *   enum.getName(v) -> string | null   (reverse lookup)
 */
function createEnum(definition) {
  const keys = [];
  const values = [];
  const result = {};

  // Internal helper: register one entry with validation.
  const addEntry = (key, value) => {
    if (typeof key !== 'string' || key.length === 0) {
      throw new TypeError('Enum key must be a non-empty string.');
    }
    if (keys.includes(key)) {
      throw new Error(`Duplicate enum key: "${key}".`);
    }
    if (typeof value !== 'string' && typeof value !== 'number') {
      throw new TypeError('Enum value must be a string or number.');
    }

    keys.push(key);
    values.push(value);
    result[key] = value;
  };

  // Parse definition.
  if (Array.isArray(definition)) {
    definition.forEach((key, index) => addEntry(key, index));
  } else if (definition && typeof definition === 'object') {
    for (const [key, value] of Object.entries(definition)) {
      addEntry(key, value);
    }
  } else {
    throw new TypeError('Definition must be an array of names or an object mapping.');
  }

  // TypeScript-style reverse mapping for numeric enums.
  // Only add when the numeric slot is not already taken by a real key.
  values.forEach((value, i) => {
    if (typeof value === 'number' && !(value in result)) {
      result[value] = keys[i];
    }
  });

  // Attach helpers as non-enumerable so Object.keys() stays clean.
  const helpers = {
    keys: () => [...keys],
    values: () => [...values],
    hasKey: (k) => keys.includes(k),
    hasValue: (v) => values.includes(v),
    getName: (v) => {
      const idx = values.indexOf(v);
      return idx === -1 ? null : keys[idx];
    },
  };

  for (const [name, fn] of Object.entries(helpers)) {
    Object.defineProperty(result, name, {
      value: fn,
      writable: false,
      enumerable: false,
      configurable: false,
    });
  }

  // Final immutability guarantee (shallow is fine: values are primitives).
  return Object.freeze(result);
}

/* ------------------------------------------------------------------ */
/* Usage examples                                                     */
/* ------------------------------------------------------------------ */

// 1) Numeric enum (auto-increment + reverse mapping like TS)
const Color = createEnum(['RED', 'GREEN', 'BLUE']);

console.log(Color.RED);        // 0
console.log(Color[0]);        // 'RED'   (reverse mapping)
console.log(Color.keys());     // ['RED','GREEN','BLUE']
console.log(Color.values());   // [0,1,2]
console.log(Color.hasValue(1));// true
console.log(Color.getName(2));// 'BLUE'

// 2) String enum
const Role = createEnum({
  ADMIN: 'admin',
  USER: 'user',
  GUEST: 'guest',
});

console.log(Role.ADMIN);      // 'admin'
console.log(Role.hasKey('USER')); // true
console.log(Role.getName('guest')); // 'GUEST'

// 3) Immutability
try {
  Color.RED = 999;            // silently fails in non-strict; throws in strict mode
  Color.NEW = 'x';            // throws in strict mode
} catch (e) {
  console.error('Mutation blocked:', e.message);
}

// 4) Membership guard pattern
function requireColor(value) {
  if (!Color.hasValue(value)) {
    throw new Error(`Invalid color value: ${value}`);
  }
  return value;
}
```

