### Key takeaways

| Concept | Practice shown |
|---|---|
| **Defaults** | `optional(name, default)` |
| **Required vars** | `required(name)` throwing at startup |
| **Type coercion** | `Number(...)` once in config |
| **Immutability** | `Object.freeze(...)` |
| **Environment-specific loading** | dotenv skipped in `production`/`test` |
| **Fail fast** | Validation runs at `require()` time |

This pattern scales to larger apps: add more fields (e.g., `logLevel`, `redisUrl`), group them, and optionally validate with a schema library like `zod` or `joi` while keeping the same structure.

## Environment Variables & Configuration in JavaScript

### What they are
- **Environment variables** are key–value pairs provided by the OS/process. In Node.js they live in `process.env` and are **always strings**.
- **Configuration** is the broader practice of externalizing values (host, port, secrets, feature flags) so the same code runs across dev/staging/prod without edits.
- Typical sources: OS env, `.env` files (local dev only), cloud secret managers, config servers.

### Key rules (interview talking points)
1. **Never commit secrets** (`.env` in `.gitignore`); commit an `.env.example` instead.
2. **Validate at startup** — fail fast on missing/invalid config; don’t let bad config surface at runtime.
3. **Coerce types** — env is strings; parse numbers/booleans explicitly.
4. **Freeze the config object** — prevent accidental mutation.
5. **Single source of truth** — one module exports a typed, validated config.
6. **Don’t read `process.env` scattered through code** — centralize.

---

## Implementation: Core Config Loader

### Option A — Robust version with Zod (recommended)

```bash
npm i zod dotenv
```

```js
// config.js
import 'dotenv/config';          // loads .env in local dev (no-op if absent)
import { z } from 'zod';

/**
 * Schema = contract for required/optional config.
 * - coerce: converts string -> number/boolean where appropriate
 * - default: supplies safe fallbacks for non-secrets
 */
const schema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000),
  HOST: z.string().min(1).default('0.0.0.0'),

  // Secrets: required, no defaults
  DATABASE_URL: z.string().url(),
  API_KEY: z.string().min(16, 'API_KEY must be at least 16 chars'),

  // Optional tuning
  LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('info'),
  REQUEST_TIMEOUT_MS: z.coerce.number().int().positive().default(5000),
});

/**
 * Load and validate configuration from a given env object.
 * Pure function -> easy to unit test with a fake env.
 */
export function loadConfig(env = process.env) {
  const result = schema.safeParse(env);

  if (!result.success) {
    // Flatten errors for readable output
    const errors = result.error.flatten().fieldErrors;
    console.error('❌ Invalid configuration:');
    for (const [key, msgs] of Object.entries(errors)) {
      console.error(`   ${key}: ${msgs.join(', ')}`);
    }
    // Fail fast: bad config shouldn't reach runtime
    throw new Error('Configuration validation failed');
  }

  // Freeze to prevent accidental mutation elsewhere
  return Object.freeze(result.data);
}

// Singleton used by the app
export const config = loadConfig();
```

Usage:

```js
// server.js
import { config } from './config.js';

console.log(`Starting on ${config.HOST}:${config.PORT} (${config.NODE_ENV})`);
```

`.env.example` (committed):

```env
NODE_ENV=development
PORT=3000
HOST=0.0.0.0
DATABASE_URL=postgres://user:pass@localhost:5432/db
API_KEY=change-me-to-a-real-secret
LOG_LEVEL=debug
REQUEST_TIMEOUT_MS=5000
```

---

### Option B — Zero-dependency core (interview-friendly)

```js
// config.js

const REQUIRED = ['DATABASE_URL', 'API_KEY'];

function parseNumber(raw, key) {
  const n = Number(raw);
  if (Number.isNaN(n)) throw new Error(`${key} must be a number, got "${raw}"`);
  return n;
}

function parseBool(raw) {
  return raw === 'true' || raw === '1';
}

/**
 * Build a typed, validated config object from process.env.
 * Defaults are applied centrally; missing required vars throw early.
 */
export function loadConfig(env = process.env) {
  // Fail fast on missing required vars
  for (const key of REQUIRED) {
    if (!env[key]) throw new Error(`Missing required env var: ${key}`);
  }

  const config = {
    nodeEnv: env.NODE_ENV ?? 'development',
    port: parseNumber(env.PORT ?? '3000', 'PORT'),
    host: env.HOST ?? '0.0.0.0',
    databaseUrl: env.DATABASE_URL,
    apiKey: env.API_KEY,
    logLevel: env.LOG_LEVEL ?? 'info',
    requestTimeoutMs: parseNumber(env.REQUEST_TIMEOUT_MS ?? '5000', 'REQUEST_TIMEOUT_MS'),
    debug: parseBool(env.DEBUG ?? 'false'),
  };

  // Simple invariant checks
  if (config.port <= 0 || config.port > 65535) {
    throw new Error(`PORT out of range: ${config.port}`);
  }
  if (!['development', 'test', 'production'].includes(config.nodeEnv)) {
    throw new Error(`Invalid NODE_ENV: ${config.nodeEnv}`);
  }

  return Object.freeze(config);
}

export const config = loadConfig();
```

---

### Testing tip (senior signal)

Because `loadConfig(env)` accepts an env object, you can unit-test it without mutating `process.env`:

```js
import { loadConfig } from './config.js';

test('throws when DATABASE_URL missing', () => {
  expect(() => loadConfig({ API_KEY: 'x'.repeat(20) })).toThrow(/DATABASE_URL/);
});

test('coerces PORT to number', () => {
  const c = loadConfig({
    DATABASE_URL: 'postgres://x',
    API_KEY: 'x'.repeat(20),
    PORT: '8080',
  });
  expect(c.port).toBe(8080);
});
```

### Summary checklist
- Centralize reads of `process.env`.
- Validate + coerce at startup; fail fast.
- Secrets required, no defaults.
- Freeze the exported config.
- Keep `.env` out of git; ship `.env.example`.
- Make loader pure/testable.

# Edge Cases with Environment Variables & Configuration in JavaScript

Environment variables are deceptively simple: every value is a **string**, loaded at process start, and often consumed in surprising contexts. Below are the most common (and costly) edge cases, each with idiomatic code.

---

## 1. Everything is a string — type coercion

`process.env` values are always `string | undefined`. Forgetting this produces subtle bugs.

```js
// ❌ "false" is truthy, 0 becomes "0" (truthy-ish), "" is falsy
if (process.env.DEBUG) { /* runs even when DEBUG=false */ }
const port = process.env.PORT + 1; // "30001" string concat

// ✅ Explicit parsers
const toBool = (v, fallback = false) => {
  if (v === undefined) return fallback;
  const s = v.trim().toLowerCase();
  if (s === '' || s === '0' || s === 'false' || s === 'no' || s === 'off') return false;
  if (s === '1' || s === 'true' || s === 'yes' || s === 'on') return true;
  throw new Error(`Invalid boolean env value: ${JSON.stringify(v)}`);
};

const toInt = (v, fallback) => {
  if (v === undefined || v === '') return fallback;
  const n = Number(v);
  if (!Number.isInteger(n)) throw new Error(`Invalid integer: ${v}`);
  return n;
};

const DEBUG = toBool(process.env.DEBUG);
const PORT  = toInt(process.env.PORT, 3000);
```

---

## 2. Missing vs. empty string

`undefined` (unset) and `""` (set but empty) are different; both often need distinct handling.

```js
// Distinguish three states
function readEnv(name) {
  if (!(name in process.env)) return { state: 'unset' };
  const v = process.env[name];
  if (v === '') return { state: 'empty' };
  return { state: 'set', value: v };
}

// Practical: empty should not silently fall back
const API_KEY = process.env.API_KEY;
if (API_KEY === undefined) throw new Error('API_KEY is required');
if (API_KEY === '') throw new Error('API_KEY must not be empty');
```

---

## 3. The `"false"` truthiness trap

The single most common bug in JS config code.

```js
// ❌
const enableCache = process.env.ENABLE_CACHE || true; // "false" → "false" (truthy)

// ✅
const enableCache = process.env.ENABLE_CACHE !== 'false';
// or stricter:
const enableCache = ['1','true','yes','on'].includes((process.env.ENABLE_CACHE ?? '').toLowerCase());
```

---

## 4. Numeric edge cases (NaN, Infinity, octal, leading zeros)

```js
function parseNumber(v, { min, max, integer = false } = {}) {
  if (v === undefined || v === '') return undefined;
  const n = Number(v.trim());
  if (Number.isNaN(n)) throw new Error(`Not a number: ${v}`);
  if (!Number.isFinite(n)) throw new Error(`Non-finite number: ${v}`);
  if (integer && !Number.isInteger(n)) throw new Error(`Not an integer: ${v}`);
  if (min !== undefined && n < min) throw new Error(`Below min ${min}: ${v}`);
  if (max !== undefined && n > max) throw new Error(`Above max ${max}: ${v}`);
  // Guard against accidental octal/hex interpretation by rejecting leading zeros
  // unless explicitly allowed
  return n;
}

// Watch out: Number("08") === 8 (fine), but parseInt("08") historically octal in old engines.
// Always pass radix: parseInt(v, 10).
```

---

## 5. `.env` file parsing quirks

dotenv (and friends) have non-obvious semantics: quotes, comments, multiline, interpolation.

```bash
# .env
PORT=3000
DEBUG=true
# inline comments are NOT stripped by dotenv (value keeps " # comment")
GREETING=hello world
QUOTED="a value with spaces"
SINGLE='no $interpolation here'
MULTI="line1\nline2"
URL=https://example.com?a=1&b=2
EMPTY=
JSON={"a":1,"b":"x"}
```

```js
import 'dotenv/config';

// Quoted values: dotenv strips surrounding quotes but NOT embedded ones inconsistently
console.log(process.env.QUOTED); // a value with spaces

// Inline comments: dotenv does NOT strip them (unless using dotenv-expand / some parsers)
// "hello world # comment" stays whole.

// Interpolation: only with dotenv-expand
// import 'dotenv-expand' ...
```

```js
// Safer: parse explicitly and validate, don't trust raw dotenv output
import dotenv from 'dotenv';
import fs from 'node:fs';

const result = dotenv.config({ path: '.env' });
if (result.error) throw result.error;

// dotenv-expand for ${VAR} references
import dotenvExpand from 'dotenv-expand';
dotenvExpand.expand(result);
```

**Edge cases to remember:**
- `#` inside unquoted values is kept.
- `\n` in double-quoted values becomes a real newline; in unquoted it stays literal `\n`.
- Backticks / shell-style `$()` are not evaluated.
- BOM at start of file can corrupt first key.
- Duplicate keys: last wins (usually), but some parsers error.
- Files with CRLF line endings: dotenv handles, but custom parsers may not.

---

## 6. BOM and whitespace in keys/values

```js
import fs from 'node:fs';

function loadEnvFile(path) {
  let raw = fs.readFileSync(path, 'utf8');
  if (raw.charCodeAt(0) === 0xFEFF) raw = raw.slice(1); // strip BOM
  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    let val = trimmed.slice(eq + 1).trim();
    // strip matching quotes
    if ((val.startsWith('"') && val.endsWith('"')) ||
        (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }
    process.env[key] = val;
  }
}
```

---

## 7. Validation with a schema (recommended)

Don't scatter `process.env.X` across the codebase. Validate once at startup.

```js
// Using zod
import { z } from 'zod';
import 'dotenv/config';

const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  PORT: z.coerce.number().int().min(1).max(65535).default(3000),
  DATABASE_URL: z.string().url(),
  REDIS_URL: z.string().url().optional(),
  DEBUG: z.string().transform(v => ['1','true','yes'].includes(v.toLowerCase())).default('false'),
  ALLOWED_ORIGINS: z.string().transform(s => s.split(',').map(x => x.trim()).filter(Boolean)),
  API_KEY: z.string().min(16),
});

const parsed = EnvSchema.safeParse(process.env);
if (!parsed.success) {
  console.error('Invalid environment:', parsed.error.flatten().fieldErrors);
  process.exit(1);
}
export const env = parsed.data; // typed, validated, frozen-ish
```

**Edge cases handled by schema:**
- Coercion of `"3000"` → `3000`.
- Required vs optional.
- Defaults applied.
- Fail-fast with readable errors.
- Single source of truth.

---

## 8. Client-side exposure (bundlers)

Frontend bundlers only expose variables with specific prefixes. Unprefixed secrets leak into bundles if imported.

```js
// Vite
const apiUrl = import.meta.env.VITE_API_URL;        // exposed to client
const secret  = import.meta.env.SECRET_KEY;         // undefined in browser (good)

// Next.js
const pub = process.env.NEXT_PUBLIC_API_URL;        // inlined into client bundle
const priv = process.env.DATABASE_URL;              // server-only; undefined on client

// Create React App
const cra = process.env.REACT_APP_API_URL;
```

**Edge cases:**
- A secret without prefix is `undefined` on client — code that assumes it exists crashes.
- `NEXT_PUBLIC_*` values are **inlined at build time**; changing them requires rebuild, not just restart.
- Never put tokens in `VITE_`/`NEXT_PUBLIC_`/`REACT_APP_` variables.
- Server components vs client components in Next.js: `process.env` access differs.

```js
// Guard against accidental client exposure
if (typeof window !== 'undefined' && process.env.DATABASE_URL) {
  throw new Error('DATABASE_URL must never reach the client bundle');
}
```

---

## 9. Defaults & fallback chains

```js
// ❌ || treats 0 and "" as missing
const retries = process.env.RETRIES || 3; // RETRIES=0 → 3 (wrong)

// ✅ nullish coalescing
const retries = process.env.RETRIES ?? 3; // only null/undefined trigger fallback

// ✅ explicit
const retries = process.env.RETRIES === undefined ? 3 : Number(process.env.RETRIES);

// Layered config: env > file > defaults
function resolve(key, { fileConfig, defaults }) {
  if (process.env[key] !== undefined) return process.env[key];
  if (Object.prototype.hasOwnProperty.call(fileConfig, key)) return fileConfig[key];
  return defaults[key];
}
```

---

## 10. Whitespace, newlines, quotes in values

```js
// Env values often arrive with trailing spaces/newlines (Docker, K8s, CI)
const raw = process.env.API_KEY;
const key = raw?.trim(); // but careful: a legitimate value may contain leading space

// JSON in env (common for service accounts)
let creds;
try {
  creds = JSON.parse(process.env.GCP_CREDENTIALS ?? '{}');
} catch (e) {
  throw new Error(`GCP_CREDENTIALS is not valid JSON: ${e.message}`);
}

// Base64 secrets
const buf = Buffer.from(process.env.SECRET_B64 ?? '', 'base64');
if (buf.length === 0 && process.env.SECRET_B64) throw new Error('bad base64');
```

---

## 11. Logging & secret leakage

```js
// ❌ Dumping entire env on error
console.error('Config:', process.env); // leaks secrets to logs/APM

// ✅ Redact known sensitive keys
const SENSITIVE = /key|secret|token|password|passwd|pwd|credential|auth/i;
function safeEnv() {
  return Object.fromEntries(
    Object.entries(process.env).map(([k, v]) =>
      SENSITIVE.test(k) ? [k, '[REDACTED]'] : [k, v]
    )
  );
}
console.error('Config:', safeEnv());

// Also redact in error messages / stack traces
function redact(str) {
  let out = str;
  for (const [k, v] of Object.entries(process.env)) {
    if (v && v.length > 4 && SENSITIVE.test(k)) {
      out = out.split(v).join('[REDACTED]');
    }
  }
  return out;
}
```

---

## 12. Runtime mutation & caching

`process.env` is mutable; modules may cache config at import time.

```js
// config.js — evaluated once
export const config = {
  port: Number(process.env.PORT ?? 3000),
};

// If PORT changes later (e.g. tests), config.port is stale.
// Prefer a function or getter for dynamic values:
export const getConfig = () => ({
  port: Number(process.env.PORT ?? 3000),
});

// In tests, reset env between cases
beforeEach(() => {
  vi.resetModules();
  process.env.PORT = '4000';
});
```

Also: child processes inherit a **snapshot** of `process.env` at spawn time.

```js
import { spawn } from 'node:child_process';
// Mutations after spawn don't propagate; pass env explicitly:
spawn('node', ['worker.js'], { env: { ...process.env, WORKER_ID: '42' } });
```

---

## 13. Environment-specific merging (config files)

```js
// config/index.js
import fs from 'node:fs';
const env = process.env.NODE_ENV ?? 'development';

const base = JSON.parse(fs.readFileSync('config/default.json', 'utf8'));
const override = fs.existsSync(`config/${env}.json`)
  ? JSON.parse(fs.readFileSync(`config/${env}.json`, 'utf8'))
  : {};

// Deep merge, env vars win last
export const config = deepMerge(base, override, envOverrides());

function envOverrides() {
  // Map ENV_VAR -> config path; only set keys present
  const out = {};
  if (process.env.DATABASE_URL) out.database = { url: process.env.DATABASE_URL };
  if (process.env.PORT) out.server = { port: Number(process.env.PORT) };
  return out;
}
```

**Edge cases:**
- `NODE_ENV` not set in production by default (some platforms set it, some don't).
- `NODE_ENV=test` triggers dev dependencies in some tools.
- Case sensitivity: `node_env` won't match.

---

## 14. Array / list parsing

```js
// CORS origins, feature flags, etc.
function parseList(v, { sep = ',', trim = true } = {}) {
  if (v === undefined || v === '') return [];
  return v.split(sep).map(x => (trim ? x.trim() : x)).filter(x => x !== '');
}

const origins = parseList(process.env.ALLOWED_ORIGINS);
// "a.com, b.com,,c.com" → ['a.com','b.com','c.com']

// Feature flags as set
const features = new Set(parseList(process.env.FEATURES));
if (features.has('new-ui')) { ... }
```

---

## 15. Cross-platform & process.env shape

```js
// On Windows, env var names are case-insensitive at OS level but JS keeps case.
// process.env.Path vs process.env.PATH — both may exist on Windows.
const path = process.env.PATH ?? process.env.Path ?? '';

// process.env is a Proxy-like object on some platforms; copying is safer
const snapshot = { ...process.env }; // plain object
```

---

## 16. Frozen config & immutability

Prevent accidental mutation of validated config.

```js
const env = Object.freeze(parsed.data);
// Deep freeze for nested
function deepFreeze(o) {
  Object.freeze(o);
  for (const v of Object.values(o)) if (v && typeof v === 'object') deepFreeze(v);
  return o;
}
```

---

## 17. Secret rotation / dynamic config

For long-running processes, env won't update. Use a config service or file watcher.

```js
import fs from 'node:fs';
let config = loadConfig();
fs.watchFile('config.json', () => { config = loadConfig(); });
export const getConfig = () => config;
```

---

## 18. Putting it together: a robust config module

```js
// config.js
import 'dotenv/config';
import { z } from 'zod';

const Schema = z.object({
  NODE_ENV: z.enum(['development','test','production']).default('development'),
  PORT: z.coerce.number().int().min(1).max(65535).default(3000),
  DATABASE_URL: z.string().url(),
  LOG_LEVEL: z.enum(['debug','info','warn','error']).default('info'),
  FEATURES: z.string().default('').transform(s =>
    new Set(s.split(',').map(x=>x.trim()).filter(Boolean))
  ),
});

const r = Schema.safeParse(process.env);
if (!r.success) {
  console.error('Bad environment:', JSON.stringify(r.error.flatten().fieldErrors));
  process.exit(1);
}
export const config = Object.freeze(r.data);
```

---

## Summary checklist

| Edge case | Mitigation |
|---|---|
| String-only values | Explicit `toBool`/`toInt`/`Number` |
| `"false"` truthy | Compare to `'false'` literally |
| Missing vs empty | Distinguish `undefined` vs `''` |
| `0`/`""` fallback | Use `??` not `\|\|` |
| NaN/Infinity | `Number.isFinite` |
| `.env` quoting/comments | Use dotenv + dotenv-expand; validate after |
| BOM/CRLF | Strip BOM; split on `/\r?\n/` |
| Client exposure | Respect `VITE_`/`NEXT_PUBLIC_` prefixes; never prefix secrets |
| Secret leakage | Redact in logs/errors |
| Stale cached config | Load lazily or reset modules in tests |
| Child processes | Pass `env` explicitly |
| Cross-platform case | Normalize keys |
| Mutation | `Object.freeze` validated config |

The single highest-leverage habit: **validate `process.env` once at startup with a schema (Zod/Joi) and export a frozen, typed object** — everything else becomes a non-issue.

```js
// error-handling.js
// Run with: node error-handling.js

'use strict';

/* ------------------------------------------------------------------ */
/* 1. Custom error classes                                             */
/* ------------------------------------------------------------------ */
class AppError extends Error {
  constructor(message, { code = 'APP_ERROR', cause } = {}) {
    super(message, { cause });          // ES2022: native cause support
    this.name = this.constructor.name;
    this.code = code;
    // V8/Node: clean stack trace
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

class ValidationError extends AppError {
  constructor(message, field) {
    super(message, { code: 'VALIDATION_ERROR' });
    this.field = field;
  }
}

class NotFoundError extends AppError {
  constructor(message, id) {
    super(message, { code: 'NOT_FOUND' });
    this.id = id;
  }
}

/* ------------------------------------------------------------------ */
/* 2. Helpers                                                          */
/* ------------------------------------------------------------------ */
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function acquireResource() {
  console.log('  [resource] acquired');
  return {
    async release() {
      await delay(5);
      console.log('  [resource] released');
    },
  };
}

/* ------------------------------------------------------------------ */
/* 3. Functions that throw                                             */
/* ------------------------------------------------------------------ */
async function fetchUser(id) {
  if (typeof id !== 'number') {
    throw new TypeError(`id must be a number, got ${typeof id}`);
  }
  if (!Number.isInteger(id) || id < 1) {
    throw new RangeError('id must be a positive integer');
  }

  await delay(10);

  if (id === 404) {
    throw new NotFoundError('User not found', id);
  }
  if (id === 500) {
    // Wrap a low-level error with context using `cause`
    const dbErr = new Error('ECONNREFUSED');
    throw new AppError('Database unavailable', { code: 'DB_DOWN', cause: dbErr });
  }

  return { id, name: `User#${id}` };
}

/* ------------------------------------------------------------------ */
/* 4. try / catch / finally with rethrow                               */
/* ------------------------------------------------------------------ */
async function processUser(id) {
  let resource = null;
  try {
    resource = await acquireResource();
    const user = await fetchUser(id);
    console.log('  OK:', user);
    return user;
  } catch (err) {
    // Differentiate by type
    if (err instanceof ValidationError) {
      console.warn('  Validation issue:', err.message, 'field=', err.field);
    } else if (err instanceof NotFoundError) {
      console.warn('  Not found:', err.message, 'id=', err.id);
    } else if (err instanceof TypeError || err instanceof RangeError) {
      console.warn('  Bad input:', err.message);
    } else if (err instanceof AppError && err.code === 'DB_DOWN') {
      console.error('  DB down, cause:', err.cause?.message);
    } else {
      // Unknown error: log and rethrow so caller can decide
      console.error('  Unexpected error:', err);
      throw err;
    }
  } finally {
    // Always runs, even on throw/return
    if (resource) await resource.release();
  }
}

/* ------------------------------------------------------------------ */
/* 5. Promise chains (.then/.catch)                                    */
/* ------------------------------------------------------------------ */
function promiseStyle(id) {
  return fetchUser(id)
    .then((u) => {
      console.log('  promise OK:', u);
      return u;
    })
    .catch((err) => {
      console.log('  promise caught:', err.name, '-', err.message);
      // Convert to a safe default instead of propagating
      return { id, name: 'Guest' };
    });
}

/* ------------------------------------------------------------------ */
/* 6. AggregateError (multiple failures)                               */
/* ------------------------------------------------------------------ */
async function fetchMany(ids) {
  const results = await Promise.allSettled(ids.map(fetchUser));
  const failures = results
    .filter((r) => r.status === 'rejected')
    .map((r) => r.reason);

  if (failures.length) {
    throw new AggregateError(failures, `${failures.length} of ${ids.length} failed`);
  }
  return results.map((r) => r.value);
}

/* ------------------------------------------------------------------ */
/* 7. Safe wrapper utility                                             */
/* ------------------------------------------------------------------ */
async function safe(fn, ...args) {
  try {
    return { ok: true, value: await fn(...args) };
  } catch (err) {
    return { ok: false, error: err };
  }
}

/* ------------------------------------------------------------------ */
/* 8. Global handlers (Node)                                           */
/* ------------------------------------------------------------------ */
process.on('unhandledRejection', (reason) => {
  console.error('UNHANDLED REJECTION:', reason);
});
// Note: uncaughtException should usually log + exit in production.
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION:', err);
});

/* ------------------------------------------------------------------ */
/* 9. Main demo                                                        */
/* ------------------------------------------------------------------ */
(async function main() {
  console.log('--- valid user ---');
  await processUser(7);

  console.log('--- not found ---');
  await processUser(404);

  console.log('--- bad input (string) ---');
  await processUser('x');

  console.log('--- bad input (negative) ---');
  await processUser(-3);

  console.log('--- db down (wrapped cause) ---');
  await processUser(500);

  console.log('--- promise style ---');
  console.log(await promiseStyle(404));

  console.log('--- fetchMany (AggregateError) ---');
  try {
    await fetchMany([1, 404, 2, 500]);
  } catch (err) {
    console.log('  AggregateError:', err.message);
    for (const e of err.errors) console.log('   -', e.name, e.message);
  }

  console.log('--- safe wrapper ---');
  console.log(await safe(fetchUser, 999));
  console.log(await safe(fetchUser, 'bad'));

  console.log('--- done ---');
})();
```

### Key concepts covered

- **`try / catch / finally`** – `finally` always runs (cleanup), even on `return` or `throw`.
- **`throw`** – can throw any value, but prefer `Error` instances for stack traces.
- **Built-in errors** – `TypeError`, `RangeError`, `ReferenceError`, `SyntaxError`, etc.
- **Custom errors** – extend `Error`, set `name`, use `Error.captureStackTrace` for clean stacks.
- **`instanceof` checks** – handle different failure modes differently.
- **Rethrowing** – log/inspect then `throw err` to let callers decide.
- **`Error` `cause` (ES2022)** – wrap low-level errors with context without losing origin.
- **Async/await** – errors become rejected promises; `try/catch` works naturally.
- **Promise chains** – `.catch()` for recovery or transformation.
- **`Promise.allSettled` + `AggregateError`** – collect multiple failures.
- **Safe wrappers** – return `{ ok, value/error }` instead of throwing.
- **Global handlers** – `unhandledRejection`, `uncaughtException` as last-resort safety nets.

Run it with `node error-handling.js` to see each path in action.

## 1. Core idea

JavaScript uses **exceptions** to signal that something unexpected happened and normal execution can’t continue. When an exception is thrown, the engine **unwinds the call stack** until it finds a matching `catch` block; if none exists, the program (or that async task) fails.

Key points:
- Exceptions are for *exceptional* situations, not normal control flow.
- Anything can be thrown, but you should almost always throw an `Error` (or subclass) so you get a stack trace.
- `finally` runs whether or not an exception occurred—great for cleanup.

---

## 2. Syntax

### Basic `try / catch / finally`

```js
try {
  const data = JSON.parse(maybeBadJson);
  console.log(data.name);
} catch (err) {
  console.error("Parse failed:", err.message);
} finally {
  console.log("Always runs");
}
```

`catch (err)` receives the thrown value. If you only need the value and not the binding, modern JS allows `catch { ... }` (optional binding).

### Throwing

```js
function divide(a, b) {
  if (b === 0) throw new Error("Division by zero");
  return a / b;
}
```

Use built-in types when they fit:

```js
throw new TypeError("Expected a number");
throw new RangeError("Index out of bounds");
throw new SyntaxError("Bad template");
```

### Custom errors

```js
class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

throw new ValidationError("email", "must contain @");
```

---

## 3. Typical use cases

### Input validation

```js
function createUser({ age }) {
  if (typeof age !== "number" || age < 0) {
    throw new RangeError("age must be a non-negative number");
  }
  return { age };
}
```

### Parsing / deserialization

```js
function loadConfig(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error(`Invalid config: ${e.message}`);
  }
}
```

### Resource cleanup (`finally`)

```js
const file = openFile();
try {
  process(file);
} finally {
  file.close(); // runs even if process throws
}
```

### Retry / recovery

```js
async function fetchWithRetry(url, tries = 3) {
  for (let i = 0; i < tries; i++) {
    try {
      return await fetch(url);
    } catch (e) {
      if (i === tries - 1) throw e;
      await new Promise(r => setTimeout(r, 200 * (i + 1)));
    }
  }
}
```

---

## 4. Async error handling

### Promises

```js
fetch("/api/user")
  .then(r => r.json())
  .catch(err => console.error("Network/parse error:", err));
```

### `async/await` (preferred)

```js
async function getUser() {
  try {
    const res = await fetch("/api/user");
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    // err may be a network error or your thrown HTTP error
    console.error(err);
    throw err; // rethrow if callers should also know
  }
}
```

### Unhandled promise rejections (global safety net)

Browser:
```js
window.addEventListener("unhandledrejection", e => {
  console.error("Unhandled promise:", e.reason);
});
```

Node.js:
```js
process.on("unhandledRejection", (reason) => {
  console.error("Unhandled rejection:", reason);
});
```

---

## 5. Best practices (short)

- **Throw `Error` objects**, not strings or primitives (strings lose stack traces).
- **Don’t swallow errors** silently; log or rethrow with context.
- **Use specific types** (`TypeError`, `RangeError`) when appropriate.
- **Keep `try` blocks small** so you know exactly what can fail.
- **Don’t use exceptions for expected branches** (e.g., “user not found” may be better as a return value).
- **Clean up in `finally`** (or use `using`/disposables where available).

---

### Minimal “all in one” example

```js
class AppError extends Error {
  constructor(code, message) {
    super(message);
    this.name = "AppError";
    this.code = code;
  }
}

async function main() {
  try {
    const n = parsePositive("abc");
    console.log(await fetchNumber(n));
  } catch (e) {
    if (e instanceof AppError) console.error(e.code, e.message);
    else console.error("Unexpected:", e);
  }
}

function parsePositive(s) {
  const n = Number(s);
  if (!Number.isFinite(n) || n <= 0) throw new AppError("BAD_INPUT", "not a positive number");
  return n;
}

async function fetchNumber(n) {
  // ...
  return n;
}
```

This covers the idea, syntax, and common patterns in idiomatic modern JavaScript.

A common mistake is **swallowing exceptions and continuing as if nothing happened**, especially by catching every error in one broad `try/catch` and returning a default value. That hides real bugs and makes failures hard to diagnose.

### Mistaken version

```js
function readConfig(text) {
  try {
    return JSON.parse(text).timeout;
  } catch (err) {
    console.error("Bad config");
    return 3000; // silently fall back
  }
}
```

### What is wrong

- **Too broad a catch:** it catches both `SyntaxError` from invalid JSON **and** `TypeError` from a valid JSON value that has no `timeout` property.
- **Silent fallback:** the caller cannot tell whether the config was valid, malformed, or simply missing a field.
- **Hidden bug:** if `text` is `"null"`, `JSON.parse` returns `null`, and `null.timeout` throws a `TypeError`. That error is swallowed and treated like “bad JSON.”
- **Poor diagnostics:** logging `"Bad config"` does not include the original error message or stack trace.

### Corrected version

```js
function readConfig(text) {
  let parsed;

  try {
    parsed = JSON.parse(text);
  } catch (err) {
    throw new Error(`Invalid config JSON: ${err.message}`);
  }

  if (
    parsed === null ||
    typeof parsed !== "object" ||
    typeof parsed.timeout !== "number" ||
    !Number.isFinite(parsed.timeout) ||
    parsed.timeout <= 0
  ) {
    throw new TypeError(
      "Config must be an object with a positive finite numeric timeout"
    );
  }

  return parsed.timeout;
}
```

### Why this is better

- **Separate concerns:** JSON parsing errors are caught and rethrown with context; validation errors are thrown explicitly.
- **No silent fallback:** invalid input fails loudly instead of pretending to be valid.
- **Preserves debugging information:** the original parse error message is included.
- **Clear contract:** callers know exactly what shape of input is accepted and what error they may receive.

If a fallback is truly desired, make it explicit and intentional rather than accidental:

```js
function readConfigOrDefault(text, defaultTimeout = 3000) {
  try {
    return readConfig(text);
  } catch (err) {
    console.warn("Using default timeout:", err.message);
    return defaultTimeout;
  }
}
```

This keeps the fallback logic at a higher level, where the decision to recover is visible and deliberate.

Below are common JavaScript error-handling pitfalls, with small examples and safer patterns.

## 1. Throwing strings or plain objects

A thrown string has no stack trace and fails `instanceof Error` checks.

```js
// Bad
throw "payment failed";

// Bad
throw { code: "PAYMENT_FAILED", message: "card declined" };

// Better
throw new Error("payment failed");
// or
class PaymentError extends Error {
  constructor(code, message, options) {
    super(message, options);
    this.name = "PaymentError";
    this.code = code;
  }
}
throw new PaymentError("CARD_DECLINED", "card declined", { cause: originalError });
```

## 2. Swallowing errors

Empty `catch` blocks make failures invisible and very hard to debug.

```js
// Bad
try {
  await saveUser(user);
} catch (e) {
  // ignored
}

// Better: handle expected errors, rethrow unexpected ones
try {
  await saveUser(user);
} catch (e) {
  if (e instanceof ValidationError) {
    return { ok: false, errors: e.details };
  }
  throw e; // programmer/infrastructure error: do not hide it
}
```

## 3. Catching too broadly

One `try` around unrelated operations can turn a database outage into “invalid JSON.”

```js
// Bad
try {
  const user = JSON.parse(input);
  await db.users.insert(user);
  await sendWelcomeEmail(user.email);
} catch (e) {
  return { ok: false, reason: "invalid input" };
}

// Better: separate parsing, persistence, and side effects
let user;
try {
  user = JSON.parse(input);
} catch (e) {
  throw new Error("invalid user JSON", { cause: e });
}

try {
  await db.users.insert(user);
} catch (e) {
  throw new Error("could not save user", { cause: e });
}
```

## 4. Forgetting `await`

`try/catch` only catches rejected promises if you await them.

```js
// Bad: fetchData() returns a promise, but is not awaited
async function load() {
  try {
    fetchData(); // rejection becomes unhandled
  } catch (e) {
    console.error(e); // never runs for async failure
  }
}

// Better
async function load() {
  try {
    await fetchData();
  } catch (e) {
    console.error(e);
    throw e;
  }
}
```

## 5. Unhandled promise rejections

Fire-and-forget promises can fail silently or crash the process.

```js
// Bad
doWork().then(result => use(result));

// Better
doWork()
  .then(result => use(result))
  .catch(err => {
    logger.error("doWork failed", err);
    // decide: retry, fallback, or rethrow
  });

// Or use async/await in an async context
async function run() {
  try {
    const result = await doWork();
    use(result);
  } catch (err) {
    logger.error("doWork failed", err);
  }
}
```

## 6. `Array.prototype.forEach` with async callbacks

`forEach` does not await callbacks, so rejections are unhandled and execution is not sequential.

```js
// Bad
items.forEach(async item => {
  await process(item); // unhandled rejections, no await
});

// Better: sequential
for (const item of items) {
  await process(item);
}

// Better: concurrent with controlled error handling
await Promise.all(items.map(item => process(item)));
```

## 7. Callbacks and ignored `err`

Node-style callbacks require explicit `err` handling. Throwing inside a callback often becomes an uncaught exception.

```js
// Bad
fs.readFile(path, (err, data) => {
  if (err) throw err; // not propagated to caller
  console.log(data);
});

// Better: convert to promises
import { readFile } from "node:fs/promises";

async function loadConfig(path) {
  try {
    return await readFile(path, "utf8");
  } catch (e) {
    if (e.code === "ENOENT") return null; // expected
    throw e; // unexpected
  }
}
```

## 8. Unhandled `EventEmitter` `"error"` events

If an `EventEmitter` emits `"error"` with no listener, Node throws and may crash the process.

```js
// Bad
const emitter = new EventEmitter();
emitter.emit("error", new Error("boom")); // throws

// Better
emitter.on("error", err => {
  logger.error("emitter failed", err);
});

// For streams, also handle close/finish carefully
stream.on("error", err => logger.error(err));
```

## 9. Errors in timers are outside surrounding `try/catch`

`setTimeout`, `setInterval`, and event listeners run later on the event loop.

```js
// Bad
try {
  setTimeout(() => {
    throw new Error("timer failed");
  }, 0);
} catch (e) {
  // never catches the timer error
}

// Better: handle inside the callback
setTimeout(() => {
  try {
    riskyTimerWork();
  } catch (e) {
    logger.error("timer failed", e);
  }
}, 0);

// Or wrap timer work in a promise
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}
```

## 10. `finally` masking the original error

A `return` or `throw` in `finally` can replace the original exception.

```js
// Bad
function readConfig() {
  try {
    throw new Error("original");
  } finally {
    return "ok"; // masks the thrown error
  }
}

// Better: cleanup only, do not return/throw from finally
function readConfig() {
  let handle;
  try {
    handle = openFile();
    return parse(handle);
  } finally {
    handle?.close(); // cleanup; let original error propagate
  }
}
```

Also avoid awaiting cleanup that can throw and mask the original:

```js
// Risky
try {
  await operation();
} finally {
  await cleanup(); // if cleanup rejects, original result/error may be lost
}

// Better: isolate cleanup failure
try {
  await operation();
} finally {
  try {
    await cleanup();
  } catch (cleanupError) {
    logger.error("cleanup failed", cleanupError);
  }
}
```

## 11. Wrapping errors without preserving cause

Creating a new error loses the original stack trace and context.

```js
// Bad
try {
  await db.query(sql);
} catch (e) {
  throw new Error("database query failed: " + e.message);
}

// Better: use Error cause (ES2022)
try {
  await db.query(sql);
} catch (e) {
  throw new Error("database query failed", { cause: e });
}
```

## 12. Async executor in `Promise` constructor

An `async` executor’s thrown errors or returned promise are ignored by the outer Promise.

```js
// Bad
const p = new Promise(async (resolve, reject) => {
  const data = await fetchData();
  resolve(data); // if fetchData rejects, p may hang or reject unhandled
});

// Better
function loadData() {
  return fetchData(); // already returns a promise
}

// If you must use new Promise, keep executor synchronous
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}
```

## 13. Cross-realm `instanceof Error` failures

Errors from iframes, VM contexts, or other realms may fail `instanceof Error`.

```js
// Bad in multi-realm code
if (err instanceof Error) { ... }

// More robust
function isError(value) {
  return Object.prototype.toString.call(value) === "[object Error]";
}

// Also duck-type when needed
if (value && typeof value.message === "string") { ... }
```

## 14. Custom error subclass setup in transpiled code

With Babel/older TypeScript targets, `extends Error` can break `instanceof` unless the prototype is fixed.

```js
class AppError extends Error {
  constructor(message) {
    super(message);
    this.name = "AppError";
    // Fix prototype chain in transpiled/older environments
    Object.setPrototypeOf(this, AppError.prototype);
  }
}
```

Modern native ESM/Node usually does not need this, but it is important for legacy bundles.

## 15. Treating programmer errors as recoverable

`TypeError`, `ReferenceError`, and assertion failures often indicate bugs. Catching them and continuing can corrupt state.

```js
// Bad
try {
  processPayment(order.total); // order may be undefined due to bug
} catch (e) {
  return "payment skipped";
}

// Better: validate at boundaries; let programmer errors crash/restart
if (!order || typeof order.total !== "number") {
  throw new TypeError("order.total must be a number");
}
```

A useful distinction:

- Operational errors: bad input, network failure, file missing. Handle/retry/fallback.
- Programmer errors: undefined property access, type mistakes. Fail fast, fix code.

## 16. TypeScript: assuming `catch` variables are `Error`

With `useUnknownInCatchVariables`, `e` is `unknown`.

```ts
// Bad
try {
  await fetchUser();
} catch (e) {
  console.log(e.message); // TS error: e is unknown
}

// Better
try {
  await fetchUser();
} catch (e) {
  if (e instanceof Error) {
    console.error(e.message);
  } else {
    console.error("Unknown failure", e);
  }
}
```

## 17. React error boundaries do not catch everything

Error boundaries catch render/lifecycle errors, not errors in event handlers, async code, or server rendering.

```jsx
// Boundary catches render errors
class ErrorBoundary extends React.Component {
  state = { hasError: false };

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidCatch(error, info) {
    logError(error, info);
  }

  render() {
    if (this.state.hasError) return <Fallback />;
    return this.props.children;
  }
}
```

Still handle async/event errors locally:

```jsx
async function handleClick() {
  try {
    await submitForm();
  } catch (e) {
    setError(e instanceof Error ? e.message : "submit failed");
  }
}
```

## 18. Misusing global handlers

`uncaughtException` and `unhandledRejection` are last-resort diagnostics, not normal recovery points.

```js
// Bad: keep serving after unknown crash
process.on("uncaughtException", err => {
  console.error(err);
});

// Better: log, cleanup, exit; let process manager restart
process.on("uncaughtException", err => {
  console.error("uncaught exception:", err);
  process.exit(1);
});

process.on("unhandledRejection", (reason, promise) => {
  console.error("unhandled rejection:", reason, promise);
  process.exit(1);
});
```

For browsers, `window.addEventListener("error", ...)` and `"unhandledrejection"` are useful for telemetry, but should not silently replace local handling.

## 19. `Promise.all` fails fast and loses other results

One rejection rejects the whole aggregate; remaining promises continue but their results are discarded.

```js
// Bad if you need all outcomes
const results = await Promise.all(tasks.map(runTask));

// Better when partial failures matter
const outcomes = await Promise.allSettled(tasks.map(runTask));

for (const outcome of outcomes) {
  if (outcome.status === "rejected") {
    logger.error("task failed", outcome.reason);
  } else {
    use(outcome.value);
  }
}
```

## 20. Depending on error messages instead of error codes

Messages change between versions/locales. Use stable codes and properties.

```js
// Bad
if (err.message.includes("ENOENT")) { ... }

// Better
if (err.code === "ENOENT") { ... }

// Custom errors
class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.name = "HttpError";
    this.status = status;
  }
}

if (err instanceof HttpError && err.status === 404) { ... }
```

## 21. Not cleaning up after partial failure

If a multi-step operation fails midway, resources or state may be left inconsistent.

```js
// Bad
async function transfer(from, to, amount) {
  await debit(from, amount);      // succeeds
  await credit(to, amount);       // fails: money disappears
}

// Better: transaction or compensating action
async function transfer(from, to, amount) {
  await debit(from, amount);
  try {
    await credit(to, amount);
  } catch (e) {
    await credit(from, amount); // compensate
    throw new Error("transfer failed; rolled back", { cause: e });
  }
}
```

## 22. Source maps and production stack traces

Minified production stacks are often useless unless source maps are configured.

```js
// In Node, enable source maps if using transpilation
// node --enable-source-maps dist/index.js

// In bundlers, configure sourceMap: true and upload maps to your error tracker.
```

Also consider `Error.stackTraceLimit` if stacks are truncated:

```js
Error.stackTraceLimit = 50;
```

## 23. JSON and validation boundaries

`JSON.parse` throws `SyntaxError`; untrusted input should be validated, not just parsed.

```js
function parseConfig(text) {
  let value;
  try {
    value = JSON.parse(text);
  } catch (e) {
    throw new Error("invalid JSON config", { cause: e });
  }

  if (!isConfig(value)) {
    throw new TypeError("config has unexpected shape");
  }

  return value;
}
```

## 24. Errors thrown during iteration can be surprising

Throwing inside `map`, `filter`, or generators propagates, but cleanup may not happen automatically.

```js
// Bad: no cleanup if transform throws
const results = items.map(item => {
  const resource = openResource(item);
  const value = transform(resource);
  resource.close();
  return value;
});

// Better
const results = items.map(item => {
  const resource = openResource(item);
  try {
    return transform(resource);
  } finally {
    resource.close();
  }
});
```

## Practical checklist

- Throw `Error` objects, not strings or plain objects.
- Use `cause` when translating errors.
- Await promises inside `try/catch`.
- Do not swallow errors silently.
- Handle expected operational errors; let programmer errors fail fast.
- Keep `finally` for cleanup only.
- Use stable error codes/properties, not message text.
- Add `"error"` listeners to emitters and streams.
- Use `Promise.allSettled` when partial failures matter.
- Preserve stack traces and source maps in production.

## Exercise

Write a small configuration loader:

- `parseConfig(jsonText)` parses a JSON string and validates:
  - top-level value must be an object
  - `host` must be a non-empty string
  - `port` must be an integer from `1` to `65535`
- Invalid input must throw a custom `ConfigError` with a machine-readable `code`
- A caller, `startApp(configText)`, must:
  - use the parsed config when valid
  - fall back to defaults for config errors
  - log unexpected errors without pretending they are config errors
  - always log a completion message

## Step-by-step solution

### 1. Create a custom error type

Custom errors make `catch` blocks precise. Extending `Error` preserves stack traces and `instanceof`.

```js
class ConfigError extends Error {
  constructor(code, message, cause) {
    super(message);
    this.name = "ConfigError";
    this.code = code;
    if (cause) this.cause = cause;
  }
}
```

### 2. Parse JSON safely

`JSON.parse` throws `SyntaxError` for malformed JSON. Wrap it so callers receive one consistent error type.

```js
let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch (err) {
  throw new ConfigError("INVALID_JSON", "Config must be valid JSON.", err);
}
```

### 3. Validate structure and fields

Validate before using the data. Each failure gets a distinct code.

```js
if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
  throw new ConfigError("INVALID_SHAPE", "Config must be a JSON object.");
}

if (typeof parsed.host !== "string" || parsed.host.trim() === "") {
  throw new ConfigError("INVALID_HOST", "`host` must be a non-empty string.");
}

if (!Number.isInteger(parsed.port) || parsed.port < 1 || parsed.port > 65535) {
  throw new ConfigError("INVALID_PORT", "`port` must be an integer from 1 to 65535.");
}
```

### 4. Handle errors at the application boundary

Only `startApp` decides fallback behavior. `parseConfig` stays pure: valid config or throw.

```js
function startApp(configText) {
  const defaults = { host: "localhost", port: 3000 };

  try {
    const config = parseConfig(configText);
    console.log("Starting with config:", config);
    return config;
  } catch (err) {
    if (err instanceof ConfigError) {
      console.error(`Config error [${err.code}]: ${err.message}`);
    } else {
      console.error("Unexpected error while loading config:", err);
    }

    console.log("Using defaults:", defaults);
    return defaults;
  } finally {
    console.log("Config load attempt finished.");
  }
}
```

### 5. Test the behavior

```js
console.log("--- valid ---");
startApp(JSON.stringify({ host: "example.com", port: 8080 }));

console.log("--- invalid JSON ---");
startApp("{not json");

console.log("--- invalid port ---");
startApp(JSON.stringify({ host: "example.com", port: 70000 }));
```

## Final solution

```js
class ConfigError extends Error {
  constructor(code, message, cause) {
    super(message);
    this.name = "ConfigError";
    this.code = code;
    if (cause) this.cause = cause;
  }
}

function parseConfig(jsonText) {
  let parsed;

  try {
    parsed = JSON.parse(jsonText);
  } catch (err) {
    throw new ConfigError("INVALID_JSON", "Config must be valid JSON.", err);
  }

  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new ConfigError("INVALID_SHAPE", "Config must be a JSON object.");
  }

  if (typeof parsed.host !== "string" || parsed.host.trim() === "") {
    throw new ConfigError("INVALID_HOST", "`host` must be a non-empty string.");
  }

  if (!Number.isInteger(parsed.port) || parsed.port < 1 || parsed.port > 65535) {
    throw new ConfigError("INVALID_PORT", "`port` must be an integer from 1 to 65535.");
  }

  return {
    host: parsed.host.trim(),
    port: parsed.port,
  };
}

function startApp(configText) {
  const defaults = { host: "localhost", port: 3000 };

  try {
    const config = parseConfig(configText);
    console.log("Starting with config:", config);
    return config;
  } catch (err) {
    if (err instanceof ConfigError) {
      console.error(`Config error [${err.code}]: ${err.message}`);
    } else {
      console.error("Unexpected error while loading config:", err);
    }

    console.log("Using defaults:", defaults);
    return defaults;
  } finally {
    console.log("Config load attempt finished.");
  }
}

// Example usage:
startApp(JSON.stringify({ host: "example.com", port: 8080 }));
```

### Why this is good practice

- `parseConfig` is pure and predictable: valid input returns a config, invalid input throws.
- Custom `code` values let the UI or logs react differently to different failures.
- `instanceof ConfigError` separates expected validation failures from bugs or environment errors.
- `finally` guarantees cleanup/logging even when an unexpected error occurs.

## Error handling & exceptions in JavaScript (interview-style)

### 1. Core concepts

- **`Error` objects**: carry `name`, `message`, and (in most engines) a `stack`. Prefer creating real `Error` instances over throwing strings.
- **`throw`**: can throw *anything*, but you should throw `Error` (or subclasses) so stack traces and tooling work.
- **`try / catch / finally`**:
  - `try` runs risky code.
  - `catch` receives the thrown value.
  - `finally` always runs (cleanup), even if you `return` or rethrow.
- **Async errors**: Promise rejections are the async equivalent of throws. With `async/await`, a rejected promise becomes a thrown error inside `try/catch`. Always handle rejections (`try/catch` or `.catch`) to avoid `unhandledRejection`.
- **Custom errors**: extend `Error` and set `name`/`code` so callers can branch on type (`instanceof`) instead of parsing messages.
- **Operational vs programmer errors**:
  - *Operational*: expected runtime failures (network down, file missing, validation). Handle/retry.
  - *Programmer*: bugs (undefined access). Fail fast, fix code; don’t silently swallow.
- **Best practices**: don’t swallow errors; normalize unknown throws; log with context; rethrow when you can’t fully handle; use `cause` to chain errors; avoid leaking internals to users.

### 2. “Core” implementation (small, reusable error-handling module)

```js
// error-core.js
// A minimal, production-flavored error-handling toolkit.

/**
 * Normalize any thrown value into a real Error.
 * Useful at boundaries (catch blocks, promise rejections).
 */
export function toError(value) {
  if (value instanceof Error) return value;
  if (typeof value === "string") return new Error(value);
  try {
    return new Error(JSON.stringify(value));
  } catch {
    return new Error(String(value));
  }
}

/**
 * Base application error. Carries a stable `code`, HTTP-ish status,
 * and optional metadata for logging/telemetry.
 */
export class AppError extends Error {
  constructor(message, options = {}) {
    const { code = "APP_ERROR", statusCode = 500, cause, meta } = options;
    super(message, { cause }); // ES2022 error cause chaining
    this.name = this.constructor.name;
    this.code = code;
    this.statusCode = statusCode;
    this.meta = meta ?? {};
    // Clean stack trace (V8)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /** Safe serialization for logs/APIs. */
  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      statusCode: this.statusCode,
      meta: this.meta,
      cause: this.cause instanceof Error ? this.cause.message : this.cause,
    };
  }
}

// Domain-specific errors (examples)
export class ValidationError extends AppError {
  constructor(message, meta) {
    super(message, { code: "VALIDATION_ERROR", statusCode: 400, meta });
  }
}

export class NotFoundError extends AppError {
  constructor(resource, meta) {
    super(`${resource} not found`, { code: "NOT_FOUND", statusCode: 404, meta });
  }
}

export class NetworkError extends AppError {
  constructor(message, meta) {
    super(message, { code: "NETWORK_ERROR", statusCode: 503, meta });
  }
}

/* ------------------------------------------------------------------ */
/* Result pattern: avoid throwing across module boundaries when useful */
/* ------------------------------------------------------------------ */

export function ok(value) {
  return { ok: true, value };
}

export function err(error) {
  return { ok: false, error: toError(error) };
}

/**
 * Run a (possibly async) function and return a Result instead of throwing.
 * Great for parsing/validation or when callers prefer explicit handling.
 */
export async function safe(fn, ...args) {
  try {
    return ok(await fn(...args));
  } catch (e) {
    return err(e);
  }
}

/* ------------------------------------------------------------------ */
/* Retry with exponential backoff + jitter + cancellation              */
/* ------------------------------------------------------------------ */

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    if (signal) {
      const onAbort = () => {
        clearTimeout(timer);
        reject(new DOMException("Aborted", "AbortError"));
      };
      if (signal.aborted) onAbort();
      else signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}

function isRetryable(error) {
  // Retry infra/network failures; don't retry validation/client errors.
  if (error instanceof AppError) {
    return error.statusCode >= 500 || error.code === "NETWORK_ERROR";
  }
  return /network|timeout|ECONN|ETIMEDOUT/i.test(error.message);
}

/**
 * Retry an async operation. Throws the last error if all attempts fail.
 */
export async function retry(fn, options = {}) {
  const {
    retries = 3,
    baseDelay = 100,
    shouldRetry = isRetryable,
    signal,
  } = options;

  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (e) {
      lastError = toError(e);
      const isLast = attempt === retries;
      if (isLast || !shouldRetry(lastError, attempt)) {
        throw lastError;
      }
      // Exponential backoff with full jitter.
      const delay = Math.random() * baseDelay * 2 ** attempt;
      await sleep(delay, signal);
    }
  }
  throw lastError; // unreachable, keeps TS/JS happy
}

/* ------------------------------------------------------------------ */
/* Assertions & centralized handling                                  */
/* ------------------------------------------------------------------ */

export function assert(condition, message = "Assertion failed", ErrorClass = AppError) {
  if (!condition) {
    throw new ErrorClass(message, { code: "ASSERTION_FAILED", statusCode: 500 });
  }
}

/**
 * Central handler: normalize, classify, log, and return the error.
 * In apps, call this at boundaries (Express error middleware, global handlers).
 */
export function handleError(error, logger = console) {
  const e = toError(error);
  const operational = e instanceof AppError;

  if (operational) {
    logger.warn?.(`[${e.code}] ${e.message}`, e.meta);
  } else {
    logger.error?.("Unexpected error:", e);
  }
  return e;
}
```

### 3. Usage example

```js
import {
  ValidationError,
  safe,
  retry,
  handleError,
} from "./error-core.js";

async function fetchUser(id) {
  if (!id) throw new ValidationError("id is required", { field: "id" });

  // Simulated network call
  return retry(
    async () => {
      const res = await fetch(`/api/users/${id}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    },
    { retries: 2, baseDelay: 50 }
  );
}

// Explicit Result style
const result = await safe(fetchUser, "");
if (!result.ok) {
  handleError(result.error);
} else {
  console.log(result.value);
}

// Traditional try/catch style
try {
  const user = await fetchUser("42");
  console.log(user);
} catch (e) {
  const normalized = handleError(e);
  // Branch on type instead of string matching
  if (normalized instanceof ValidationError) {
    // show form error
  }
}
```

### 4. Global safety nets (mention in interview)

- **Node**: `process.on("unhandledRejection", (r) => handleError(r))` and `process.on("uncaughtException", ...)`. Prefer crashing for programmer errors after logging.
- **Browser**: `window.addEventListener("error", ...)` and `window.addEventListener("unhandledrejection", ...)`.
- **Frameworks**: Express error middleware `(err, req, res, next) => ...`; React Error Boundaries for render errors.

### 5. Common edge cases / gotchas

- `catch (e)` where `e` may not be an `Error` → always normalize with `toError`.
- `finally` runs even on `return`; don’t put `return` in `finally` (it can mask errors).
- Async errors inside callbacks (e.g., `setTimeout`) are **not** caught by surrounding `try/catch` → handle inside callback or promisify.
- Avoid `catch {}` empty blocks; at minimum log or rethrow.
- Prefer `cause` chaining when wrapping lower-level errors.

This gives you both the conceptual model and a clean, reusable core you can drop into a real codebase.

Below are the most important edge cases when using `try/catch`, `throw`, and exceptions in JavaScript. Each section includes a problematic pattern and a safer pattern.

---

## 1. `try/catch` only catches synchronous errors in the same execution frame

A `try` block does not catch errors thrown later by timers, callbacks, or unresolved promises.

```js
// ❌ Not caught
try {
  setTimeout(() => {
    throw new Error("async timer error");
  }, 0);
} catch (e) {
  console.error("never reached");
}

// ❌ Not caught
try {
  Promise.reject(new Error("async rejection"));
} catch (e) {
  console.error("never reached");
}
```

**Safer pattern:** move error handling to the async boundary.

```js
setTimeout(() => {
  try {
    throw new Error("async timer error");
  } catch (e) {
    console.error("caught in timer:", e.message);
  }
}, 0);

Promise.reject(new Error("async rejection"))
  .catch(e => console.error("caught promise:", e.message));
```

---

## 2. `async/await` errors must be awaited or explicitly caught

```js
async function load() {
  throw new Error("load failed");
}

// ❌ Unhandled rejection
load();

// ✅ Caught
(async () => {
  try {
    await load();
  } catch (e) {
    console.error(e.message);
  }
})();
```

Also watch `Promise.all`: one rejection rejects the whole aggregate quickly.

```js
const results = await Promise.allSettled([
  fetch("/a"),
  fetch("/b"),
]);

for (const r of results) {
  if (r.status === "rejected") {
    console.error("partial failure:", r.reason);
  }
}
```

Use `Promise.allSettled` when partial failures are acceptable.

---

## 3. Throwing non-`Error` values loses stack traces and metadata

```js
// ❌ e is a string; no stack, no cause, poor debugging
try {
  throw "boom";
} catch (e) {
  console.log(typeof e, e);
}
```

**Safer pattern:** always throw `Error` instances. If integrating with untrusted code, normalize caught values.

```js
function normalizeError(value) {
  if (value instanceof Error) return value;
  if (typeof value === "string") return new Error(value);
  return new Error("Unknown thrown value", { cause: value });
}

try {
  throw 42;
} catch (e) {
  throw normalizeError(e);
}
```

---

## 4. Cross-realm `instanceof Error` can be false

An error created in an iframe, VM, or worker may not pass `instanceof Error` in the parent realm.

```js
const iframe = document.createElement("iframe");
document.body.appendChild(iframe);
const ForeignError = iframe.contentWindow.Error;
const e = new ForeignError("from iframe");

console.log(e instanceof Error); // false
```

**Safer checks:**

```js
function isErrorLike(value) {
  return (
    value !== null &&
    typeof value === "object" &&
    typeof value.message === "string" &&
    (typeof value.stack === "string" || value.stack === undefined)
  );
}
```

For host errors, duck-typing is more robust than `instanceof`.

---

## 5. `finally` can mask both return values and exceptions

### Return override

```js
function getValue() {
  try {
    return 1;
  } finally {
    return 2; // ❌ overrides the try return
  }
}
console.log(getValue()); // 2
```

### Exception masking

```js
function risky() {
  try {
    throw new Error("original");
  } finally {
    throw new Error("cleanup failed"); // ❌ hides "original"
  }
}
```

**Safer pattern:** never return from `finally`; capture cleanup errors separately.

```js
function risky() {
  let originalError;
  try {
    throw new Error("original");
  } catch (e) {
    originalError = e;
    throw e;
  } finally {
    try {
      cleanup();
    } catch (cleanupError) {
      if (!originalError) throw cleanupError;
      // Optionally attach cleanupError as cause if supported
      console.error("cleanup failed after:", originalError.message, cleanupError);
    }
  }
}
```

---

## 6. Control flow in `catch` and `finally`

`return`, `break`, and `continue` inside `catch`/`finally` can make control flow surprising.

```js
function demo(x) {
  try {
    if (x < 0) throw new Error("negative");
    return "ok";
  } catch (e) {
    return "caught"; // exits function
  } finally {
    console.log("finally always runs");
  }
}
```

A `finally` with `return` overrides an earlier `return` from `try` or `catch`. Treat `finally` as cleanup-only.

---

## 7. Preserve causal chains with `Error.cause`

Without chaining, root causes are lost.

```js
// ❌ Root cause discarded
try {
  JSON.parse("{bad");
} catch (e) {
  throw new Error("Config parse failed");
}

// ✅ Preserve cause (ES2022)
try {
  JSON.parse("{bad");
} catch (e) {
  throw new Error("Config parse failed", { cause: e });
}
```

When catching, inspect `.cause` recursively if needed.

---

## 8. `AggregateError` for multiple failures

When several independent operations fail, throwing one error loses the others.

```js
async function fetchAll(urls) {
  const results = await Promise.allSettled(urls.map(u => fetch(u)));
  const errors = results
    .filter(r => r.status === "rejected")
    .map(r => r.reason);

  if (errors.length) {
    throw new AggregateError(errors, "Some requests failed");
  }

  return results.map(r => r.value);
}
```

`AggregateError` stores `.errors` and is useful for tooling and retry logic.

---

## 9. Stack trace limits and custom error classes

V8 limits stack traces to `Error.stackTraceLimit` (default often 10).

```js
Error.stackTraceLimit = 50;
```

Custom errors should preserve class name and avoid including the constructor in the stack.

```js
class AppError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = this.constructor.name;
    // V8: remove constructor frame
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

class NotFoundError extends AppError {}
```

Avoid `throw new Error()` subclass instances losing prototype chain in older transpilation; use proper class extension.

---

## 10. Errors in callbacks are not caught by caller `try/catch`

```js
function readFileSafe(path, cb) {
  fs.readFile(path, (err, data) => {
    if (err) {
      // ❌ Throwing here becomes an uncaught exception
      // throw err;
    }
    cb(null, data);
  });
}
```

**Safer pattern:** propagate through callback or convert to promises.

```js
function readFileSafe(path) {
  return new Promise((resolve, reject) => {
    fs.readFile(path, (err, data) => {
      if (err) reject(err);
      else resolve(data);
    });
  });
}
```

---

## 11. Global unhandled error handlers

Browser:

```js
window.addEventListener("error", (event) => {
  console.error("Uncaught:", event.error);
  // event.preventDefault(); // avoid default console in some cases
});

window.addEventListener("unhandledrejection", (event) => {
  console.error("Unhandled promise rejection:", event.reason);
  event.preventDefault();
});
```

Node.js:

```js
process.on("uncaughtException", (err, origin) => {
  console.error("uncaughtException:", err, origin);
  process.exit(1); // recommended after logging
});

process.on("unhandledRejection", (reason, promise) => {
  console.error("unhandledRejection:", reason);
});
```

Do not use these as a substitute for local `try/catch`; they are last-resort diagnostics.

---

## 12. `finally` and async cleanup

Async cleanup inside `finally` must be awaited, otherwise errors escape.

```js
async function withResource() {
  const resource = await acquire();
  try {
    return await use(resource);
  } finally {
    // ❌ fire-and-forget cleanup
    release(resource).catch(console.error);
  }
}
```

**Safer pattern:**

```js
async function withResource() {
  const resource = await acquire();
  try {
    return await use(resource);
  } finally {
    await release(resource); // errors propagate or are handled here
  }
}
```

---

## 13. Generators and `generator.throw()`

Errors can be injected into a generator at its suspension point.

```js
function* gen() {
  try {
    yield 1;
    yield 2;
  } catch (e) {
    console.log("caught inside generator:", e.message);
    yield "recovered";
  }
}

const g = gen();
console.log(g.next().value); // 1
console.log(g.throw(new Error("injected")).value); // "recovered"
```

Edge case: if the generator has already completed, `throw()` throws.

```js
try {
  g.throw(new Error("too late"));
} catch (e) {
  console.error("cannot throw into completed generator:", e.message);
}
```

---

## 14. Async generators and cleanup

```js
async function* lines(source) {
  const reader = source.getReader();
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      yield value;
    }
  } finally {
    await reader.cancel(); // runs on break/return/throw
  }
}
```

Ensure `finally` handles both normal completion and early termination.

---

## 15. AbortController / `AbortError`

Fetch and many APIs throw `AbortError` when aborted. It is often not a “real” failure.

```js
async function fetchData(url, signal) {
  try {
    const res = await fetch(url, { signal });
    return await res.json();
  } catch (e) {
    if (e.name === "AbortError") {
      console.log("Request aborted by user");
      return null;
    }
    throw e;
  }
}

const controller = new AbortController();
fetchData("/data", controller.signal);
controller.abort();
```

Check `e.name`, not `instanceof`, because `AbortError` is usually a `DOMException`.

---

## 16. `DOMException` and host-thrown errors

Browsers throw `DOMException` with a `.name` such as `NotAllowedError`, `SecurityError`, `QuotaExceededError`.

```js
try {
  document.requestFullscreen();
} catch (e) {
  if (e instanceof DOMException) {
    console.error("DOM error:", e.name, e.message);
  } else {
    throw e;
  }
}
```

Do not assume all thrown errors are generic `Error` objects.

---

## 17. Serialization: `JSON.stringify(new Error(...))` is empty

`Error` properties like `message`, `stack`, and `name` are non-enumerable in many engines.

```js
const e = new Error("msg");
console.log(JSON.stringify(e)); // "{}"
```

**Safer pattern:**

```js
function serializeError(error) {
  if (!(error instanceof Error)) return { value: error };
  return {
    name: error.name,
    message: error.message,
    stack: error.stack,
    cause: error.cause ? serializeError(error.cause) : undefined,
  };
}
```

---

## 18. Optional catch binding can hide mistakes

```js
try {
  riskyOperation();
} catch {
  // ❌ No error object; easy to ignore real failures
}
```

Use only for genuinely expected, irrelevant failures, and document why.

```js
try {
  localStorage.removeItem("temp");
} catch {
  // Storage may be unavailable; safe to ignore
}
```

---

## 19. TypeScript/runtime mismatch: only runtime errors are caught

TypeScript cannot catch runtime errors. Narrow carefully.

```js
try {
  JSON.parse(input);
} catch (e) {
  // In modern TS, e is unknown by default with useUnknownInCatchVariables
  if (e instanceof SyntaxError) {
    console.error("bad JSON");
  } else {
    throw e;
  }
}
```

---

## 20. Errors in event listeners do not propagate to callers

```js
button.addEventListener("click", () => {
  throw new Error("handler error"); // reported globally, not caught by caller
});

try {
  button.click();
} catch (e) {
  // never reached
}
```

Handle inside the handler or use global handlers for reporting.

---

## 21. Web Workers and cross-thread errors

Worker errors surface via `onerror`, not through the calling thread.

```js
const worker = new Worker("worker.js");
worker.onerror = (e) => {
  console.error("Worker error:", e.message, e.filename, e.lineno);
};
worker.onmessageerror = (e) => {
  console.error("Message deserialization error:", e.data);
};
```

---

## 22. Top-level `await` in modules

An unhandled rejection from top-level `await` can fail module loading and dependents.

```js
// module.js
await riskyInit(); // if rejected, module graph fails
```

Wrap initialization if graceful degradation is desired.

```js
try {
  await riskyInit();
} catch (e) {
  console.error("Init failed, using fallback:", e);
  useFallback();
}
```

---

## Summary checklist

- Catch async errors at the async boundary, not with surrounding `try`.
- Always throw `Error` instances; normalize unknown thrown values.
- Avoid returning from `finally`; avoid throwing in `finally` without preserving original errors.
- Preserve root causes with `Error.cause`.
- Use `Promise.allSettled` and `AggregateError` for partial failures.
- Do not rely on cross-realm `instanceof`.
- Do not rely on JSON serialization of `Error`.
- Treat `AbortError` and `DOMException` specially.
- Handle global unhandled errors only as diagnostics.
- Add cleanup in `finally` with proper awaiting.

If you want, I can also provide a small utility module combining normalization, serialization, and safe async wrapping.

Below is a **complete, runnable, from-scratch event-loop simulator** in JavaScript (Node.js).  
It implements the two core queues that make the real JavaScript event loop work:

- **Task queue (macrotasks)** – things like `setTimeout`, `setInterval`
- **Microtask queue** – things like `queueMicrotask`, Promise `.then`

It preserves the most important invariant of a real event loop:

> **After every macrotask finishes, the engine drains the entire microtask queue (including microtasks created while draining) before taking the next macrotask.**

---

## `eventloop.js`

```js
'use strict';

/**
 * A small but faithful event-loop simulator.
 *
 * - Virtual clock (loop.now) instead of real wall-clock time.
 * - Tasks (macrotasks) are scheduled with delays.
 * - Microtasks are drained after every task.
 * - Supports setTimeout, setInterval, clearTimeout, clearInterval, queueMicrotask.
 */
class MiniEventLoop {
  constructor() {
    this.now = 0;                 // virtual time
    this.tasks = [];              // macrotask list
    this.microtasks = [];         // microtask queue
    this.cancelled = new Set();   // cancelled task ids
    this.nextId = 1;
  }

  /* ---------- public scheduling API ---------- */

  setTimeout(cb, delay = 0) {
    const id = this.nextId++;
    this.tasks.push({
      id,
      runAt: this.now + Math.max(0, delay),
      cb,
      repeat: 0, // 0 = one-shot
    });
    return id;
  }

  setInterval(cb, delay) {
    const id = this.nextId++;
    const d = Math.max(0, delay);
    this.tasks.push({
      id,
      runAt: this.now + d,
      cb,
      repeat: d, // >0 = repeating
    });
    return id;
  }

  clearTimeout(id)  { this.cancelled.add(id); }
  clearInterval(id) { this.cancelled.add(id); }

  queueMicrotask(cb) {
    this.microtasks.push(cb);
  }

  /* ---------- internals ---------- */

  _removeCancelled() {
    this.tasks = this.tasks.filter(t => !this.cancelled.has(t.id));
  }

  _hasWork() {
    this._removeCancelled();
    return this.tasks.length > 0 || this.microtasks.length > 0;
  }

  _drainMicrotasks() {
    // Drain recursively: microtasks queued *while* draining also run.
    let i = 0;
    while (i < this.microtasks.length) {
      const cb = this.microtasks[i++];
      try {
        cb();
      } catch (err) {
        console.error('[microtask error]', err);
      }
    }
    this.microtasks.length = 0;
  }

  _nextDueTaskIndex() {
    let idx = -1;
    for (let i = 0; i < this.tasks.length; i++) {
      const t = this.tasks[i];
      if (this.cancelled.has(t.id)) continue;
      if (t.runAt <= this.now) {
        if (idx === -1 || t.runAt < this.tasks[idx].runAt) idx = i;
      }
    }
    return idx;
  }

  _nextFutureRunAt() {
    let min = Infinity;
    for (const t of this.tasks) {
      if (this.cancelled.has(t.id)) continue;
      if (t.runAt < min) min = t.runAt;
    }
    return min;
  }

  /* ---------- main loop ---------- */

  /**
   * Run until there is no more work.
   * In a real browser/Node loop this never "returns" in the same way;
   * here we run to completion for determinism.
   */
  run() {
    let guard = 0;
    const MAX = 1_000_000;

    while (this._hasWork() && guard < MAX) {
      guard++;

      // 1) Microtasks always run before the next macrotask.
      this._drainMicrotasks();
      if (!this._hasWork()) break;

      // 2) Find a task that is due now.
      let idx = this._nextDueTaskIndex();

      // 3) Nothing due yet -> advance virtual time to the next timer.
      if (idx === -1) {
        const next = this._nextFutureRunAt();
        if (!isFinite(next)) break;
        this.now = next;
        idx = this._nextDueTaskIndex();
        if (idx === -1) break;
      }

      // 4) Run exactly one macrotask.
      const task = this.tasks.splice(idx, 1)[0];
      if (this.cancelled.has(task.id)) continue;

      try {
        task.cb();
      } catch (err) {
        console.error('[task error]', err);
      }

      // 5) Re-schedule repeating tasks.
      if (task.repeat > 0 && !this.cancelled.has(task.id)) {
        task.runAt = this.now + task.repeat;
        this.tasks.push(task);
      }
    }

    // Final microtask flush.
    this._drainMicrotasks();
    if (guard >= MAX) console.warn('MiniEventLoop: guard limit hit');
  }
}

/* ------------------------------------------------------------------ */
/* Demo / examples                                                     */
/* ------------------------------------------------------------------ */

function demoBasicOrdering() {
  console.log('\n=== Demo 1: task vs microtask ordering ===');
  const loop = new MiniEventLoop();

  console.log('script start');

  loop.queueMicrotask(() => console.log('microtask #1 (initial)'));
  loop.setTimeout(() => {
    console.log('timeout callback');
    loop.queueMicrotask(() => console.log('microtask after timeout'));
  }, 0);
  loop.queueMicrotask(() => console.log('microtask #2 (initial)'));

  loop.run();
  console.log('script end');
}

function demoVirtualTime() {
  console.log('\n=== Demo 2: timers & virtual time ===');
  const loop = new MiniEventLoop();

  loop.setTimeout(() => console.log(`fired at t=${loop.now} (delay 50)`), 50);
  loop.setTimeout(() => console.log(`fired at t=${loop.now} (delay 10)`), 10);
  loop.setTimeout(() => console.log(`fired at t=${loop.now} (delay 0)`), 0);

  loop.run();
}

function demoIntervalAndCancel() {
  console.log('\n=== Demo 3: interval + clear ===');
  const loop = new MiniEventLoop();

  let n = 0;
  const id = loop.setInterval(() => {
    n++;
    console.log(`tick ${n} at t=${loop.now}`);
    if (n === 3) {
      console.log('clearing interval');
      loop.clearInterval(id);
    }
  }, 10);

  loop.run();
  console.log(`done, total ticks = ${n}`);
}

function demoMicrotaskRecursion() {
  console.log('\n=== Demo 4: microtasks queued while draining ===');
  const loop = new MiniEventLoop();

  loop.queueMicrotask(function a() {
    console.log('microtask a');
    loop.queueMicrotask(function b() {
      console.log('microtask b (queued during a)');
    });
  });

  loop.run();
}

function main() {
  demoBasicOrdering();
  demoVirtualTime();
  demoIntervalAndCancel();
  demoMicrotaskRecursion();
}

main();
```

