## Browser: writing or saving files

Browsers cannot silently write arbitrary files. Common patterns:

### 1. Trigger a download from in-memory data

```js
function downloadText(filename, text) {
  const blob = new Blob([text], { type: "text/plain" });
  const url = URL.createObjectURL(blob);

  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();

  URL.revokeObjectURL(url);
}

downloadText("report.txt", "Generated in browser");
```

### 2. File System Access API (Chromium-based browsers)

Lets the user choose a save location with a native picker.

```js
async function saveFile() {
  try {
    const handle = await window.showSaveFilePicker({
      suggestedName: "note.txt",
      types: [{ accept: { "text/plain": [".txt"] } }],
    });

    const writable = await handle.createWritable();
    await writable.write("Saved through File System Access API");
    await writable.close();
  } catch (err) {
    if (err.name !== "AbortError") console.error(err);
  }
}
```

For reading with the same API:

```js
const [handle] = await window.showOpenFilePicker();
const file = await handle.getFile();
const text = await file.text();
```

