## Core implementation (Node.js)

```js
// file-io.js
// A small, robust wrapper around Node's filesystem APIs.
// Uses ESM; run with Node 18+.

import {
  readFile as fsReadFile,
  writeFile as fsWriteFile,
  appendFile as fsAppendFile,
  mkdir,
  stat,
  rename,
  unlink,
} from 'node:fs/promises';
import { createReadStream, createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';

/** Custom error so callers can distinguish I/O failures. */
export class FileIOError extends Error {
  constructor(message, { code, path, cause } = {}) {
    super(message);
    this.name = 'FileIOError';
    this.code = code;
    this.path = path;
    this.cause = cause;
  }
}

export class FileIO {
  /**
   * Read a file as text (or Buffer if encoding is null).
   * @param {string} path
   * @param {BufferEncoding|null} [encoding='utf8']
   */
  async read(path, encoding = 'utf8') {
    try {
      return await fsReadFile(path, encoding);
    } catch (err) {
      throw new FileIOError(`Failed to read file: ${path}`, {
        code: err.code,
        path,
        cause: err,
      });
    }
  }

  /**
   * Read and parse JSON. Throws on invalid JSON.
   */
  async readJSON(path) {
    const text = await this.read(path, 'utf8');
    try {
      return JSON.parse(text);
    } catch (err) {
      throw new FileIOError(`Invalid JSON in ${path}`, { path, cause: err });
    }
  }

  /**
   * Write data to a file.
   * @param {string} path
   * @param {string|Buffer|Uint8Array} data
   * @param {object} [opts]
   * @param {BufferEncoding} [opts.encoding='utf8']
   * @param {boolean} [opts.mkdirs=false] create parent dirs
   * @param {boolean} [opts.atomic=false] write via temp file + rename
   */
  async write(path, data, opts = {}) {
    const { encoding = 'utf8', mkdirs = false, atomic = false } = opts;

    try {
      if (mkdirs) {
        await mkdir(dirname(path), { recursive: true });
      }

      if (atomic) {
        const tmp = `${path}.${randomUUID()}.tmp`;
        await fsWriteFile(tmp, data, typeof data === 'string' ? { encoding } : undefined);
        await rename(tmp, path);
      } else {
        await fsWriteFile(path, data, typeof data === 'string' ? { encoding } : undefined);
      }
    } catch (err) {
      throw new FileIOError(`Failed to write file: ${path}`, {
        code: err.code,
        path,
        cause: err,
      });
    }
  }

  /**
   * Write JSON with pretty formatting.
   */
  async writeJSON(path, value, opts = {}) {
    const text = JSON.stringify(value, null, 2) + '\n';
    return this.write(path, text, { ...opts, encoding: 'utf8' });
  }

  /**
   * Append to a file (creates it if missing).
   */
  async append(path, data, encoding = 'utf8') {
    try {
      await fsAppendFile(path, data, typeof data === 'string' ? { encoding } : undefined);
    } catch (err) {
      throw new FileIOError(`Failed to append to file: ${path}`, {
        code: err.code,
        path,
        cause: err,
      });
    }
  }

  /**
   * Stream-copy a large file without loading it into memory.
   * Uses pipeline() which handles backpressure and cleanup.
   */
  async copy(src, dest, { mkdirs = false } = {}) {
    try {
      if (mkdirs) await mkdir(dirname(dest), { recursive: true });
      await pipeline(createReadStream(src), createWriteStream(dest));
    } catch (err) {
      throw new FileIOError(`Failed to copy ${src} -> ${dest}`, {
        code: err.code,
        path: src,
        cause: err,
      });
    }
  }

  /**
   * Check existence without throwing.
   */
  async exists(path) {
    try {
      await stat(path);
      return true;
    } catch (err) {
      if (err.code === 'ENOENT') return false;
      throw new FileIOError(`Failed to stat: ${path}`, { code: err.code, path, cause: err });
    }
  }

  /**
   * Remove a file (idempotent-ish: ignores ENOENT).
   */
  async remove(path) {
    try {
      await unlink(path);
    } catch (err) {
      if (err.code !== 'ENOENT') {
        throw new FileIOError(`Failed to remove: ${path}`, { code: err.code, path, cause: err });
      }
    }
  }
}

// ---------------- Example usage ----------------
// (async () => {
//   const io = new FileIO();
//   await io.write('/tmp/demo.txt', 'hello\n', { mkdirs: true, atomic: true });
//   console.log(await io.read('/tmp/demo.txt'));
//   await io.append('/tmp/demo.txt', 'world\n');
//   await io.writeJSON('/tmp/demo.json', { ok: true }, { mkdirs: true });
//   await io.copy('/tmp/demo.txt', '/tmp/demo.copy.txt', { mkdirs: true });
//   console.log('exists copy:', await io.exists('/tmp/demo.copy.txt'));
// })();
```

### Why this design (interview talking points)
- **Promise-based** (`fs/promises`) keeps code flat and composable.
- **Custom `FileIOError`** preserves `code`/`path` so callers can branch on `ENOENT` vs `EACCES`.
- **`atomic` write** prevents readers from seeing half-written files (common in config/lock scenarios).
- **`pipeline()`** is preferred over manual `.pipe()` because it propagates errors and cleans up streams.
- **`mkdirs`** keeps callers from repeating boilerplate.
- **No sync calls** in the happy path → doesn’t block the event loop.

### Browser counterpart (quick sketch)
```js
// Reading a user-selected file
input.addEventListener('change', async (e) => {
  const file = e.target.files[0];
  const text = await file.text();          // or new FileReader()
  console.log(text);
});

// "Writing" = download
function download(filename, content) {
  const blob = new Blob([content], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), { href: url, download: filename });
  a.click();
  URL.revokeObjectURL(url);
}
```

